// SPDX-License-Identifier: BSD-3-Clause
pragma solidity ^0.8.25;

import { IERC20Upgradeable } from "@openzeppelin/contracts-upgradeable/token/ERC20/IERC20Upgradeable.sol";
import { ResilientOracleInterface } from "@venusprotocol/oracle/contracts/interfaces/OracleInterface.sol";

interface IVToken is IERC20Upgradeable {
    function accrueInterest() external returns (uint256);

    function redeem(uint256 redeemTokens) external returns (uint256);

    function redeemUnderlying(uint256 redeemAmount) external returns (uint256);

    function borrowBalanceCurrent(address borrower) external returns (uint256);

    function balanceOfUnderlying(address owner) external returns (uint256);

    function seize(address liquidator, address borrower, uint seizeTokens) external returns (uint);

    function mintBehalf(address receiver, uint mintAmount) external returns (uint);

    function borrowBehalf(address borrower, uint borrowAmount) external returns (uint256);

    function repayBorrowBehalf(address borrower, uint repayAmount) external returns (uint256);

    function redeemUnderlyingBehalf(address redeemer, uint redeemAmount) external returns (uint);

    function redeemBehalf(address redeemer, uint redeemTokens) external returns (uint);

    function comptroller() external view returns (IComptroller);

    function borrowBalanceStored(address account) external view returns (uint256);

    function exchangeRateCurrent() external returns (uint256);

    function underlying() external view returns (address);
}

interface IVBNB is IVToken {
    function repayBorrowBehalf(address borrower) external payable;

    function liquidateBorrow(address borrower, IVToken vTokenCollateral) external payable;
}

interface IComptroller {
    enum Action {
        MINT,
        REDEEM,
        BORROW,
        REPAY,
        SEIZE,
        LIQUIDATE,
        TRANSFER,
        ENTER_MARKET,
        EXIT_MARKET
    }

    function _setActionsPaused(address[] calldata markets_, Action[] calldata actions_, bool paused_) external;

    function enterMarkets(address[] calldata vTokens) external returns (uint256[] memory);

    function enterMarketBehalf(address onBehalf, address vToken) external returns (uint256);

    function enterMarket(address user, address vToken) external returns (uint256);

    function liquidationIncentiveMantissa() external view returns (uint256);

    function vaiController() external view returns (address);

    function liquidatorContract() external view returns (address);

    function oracle() external view returns (ResilientOracleInterface);

    function actionPaused(address market, Action action) external view returns (bool);

    function markets(address) external view returns (bool, uint256, bool);

    function isForcedLiquidationEnabled(address) external view returns (bool);

    function approvedDelegates(address borrower, address delegate) external view returns (bool);

    function updateDelegate(address delegate, bool approved) external;

    function getAccountLiquidity(address account) external view returns (uint256, uint256, uint256);

    function checkMembership(address account, IVToken vToken) external view returns (bool);

    function getBorrowingPower(
        address account
    ) external view returns (uint256 error, uint256 liquidity, uint256 shortfall);

    function treasuryPercent() external view returns (uint256);

    function executeFlashLoan(
        address payable onBehalf,
        address payable receiver,
        IVToken[] memory vTokens,
        uint256[] memory underlyingAmounts,
        bytes memory param
    ) external;
}

interface IFlashLoanReceiver {
    /**
     * @notice Executes an operation after receiving the flash-borrowed assets.
     * @dev Implementation of this function must ensure at least the premium (fee) is repaid within the same transaction.
     *      Any unpaid balance (principal + premium - repaid amount) will be added to the onBehalf address's borrow balance.
     * @param vTokens The vToken contracts corresponding to the flash-borrowed underlying assets.
     * @param amounts The amounts of each underlying asset that were flash-borrowed.
     * @param premiums The premiums (fees) associated with each flash-borrowed asset.
     * @param initiator The address that initiated the flash loan.
     * @param onBehalf The address of the user whose debt position will be used for any unpaid flash loan balance.
     * @param param Additional parameters encoded as bytes. These can be used to pass custom data to the receiver contract.
     * @return success True if the operation succeeds (regardless of repayment amount), false if the operation fails.
     * @return repayAmounts Array of uint256 representing the amounts to be repaid for each asset. The receiver contract
     *         must approve these amounts to the respective vToken contracts before this function returns.
     */
    function executeOperation(
        IVToken[] calldata vTokens,
        uint256[] calldata amounts,
        uint256[] calldata premiums,
        address initiator,
        address onBehalf,
        bytes calldata param
    ) external returns (bool success, uint256[] memory repayAmounts);
}

interface IWBNB is IERC20Upgradeable {
    function deposit() external payable;

    function withdraw(uint256 amount) external;
}

interface IProtocolShareReserve {
    enum IncomeType {
        SPREAD,
        LIQUIDATION,
        ERC4626_WRAPPER_REWARDS,
        FLASHLOAN
    }

    function updateAssetsState(address comptroller, address asset, IncomeType incomeType) external;
}

contracts/LeverageManager/ILeverageStrat.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.28;

import { IVToken } from "../Interfaces.sol";

/**
 * @title ILeverageStrategiesManager
 * @author Venus Protocol
 * @notice Interface for the Leverage Strategies Manager contract
 * @dev This interface defines the functionality for entering and exiting leveraged positions
 *      using flash loans and token swaps. The contract allows users to amplify their exposure
 *      to specific assets by borrowing against their collateral and reinvesting the borrowed funds.
 */
interface ILeverageStrategiesManager {
    /// @custom:error MintBehalfFailed mintBehalf on a vToken market returned a non-zero error code
    error MintBehalfFailed(uint256 errorCode);

    /// @custom:error BorrowBehalfFailed borrowBehalf on a vToken market returned a non-zero error code
    error BorrowBehalfFailed(uint256 errorCode);

    /// @custom:error RepayBehalfFailed repayBehalf on a vToken market returned a non-zero error code
    error RepayBehalfFailed(uint256 errorCode);

    /// @custom:error RedeemBehalfFailed redeemBehalf on a vToken market returned a non-zero error code
    error RedeemBehalfFailed(uint256 errorCode);

    /// @custom:error OperationCausesLiquidation Operation would put the account at risk (undercollateralized) returns a non-zero error code from getBorrowingPower
    error OperationCausesLiquidation(uint256 errorCode);

    /// @custom:error TokenSwapCallFailed Swap helper call reverted or returned false
    error TokenSwapCallFailed();

    /// @custom:error FlashLoanAssetOrAmountMismatch Invalid flash loan arrays length or >1 elements
    error FlashLoanAssetOrAmountMismatch();

    /// @custom:error UnauthorizedExecutor Caller is not the expected Comptroller
    error UnauthorizedExecutor();

    /// @custom:error InvalidExecuteOperation Unknown operation type in flash loan callback
    error InvalidExecuteOperation();

    /// @custom:error SlippageExceeded Swap output lower than required minimum
    error SlippageExceeded();

    /// @custom:error InsufficientFundsToRepayFlashloan Not enough proceeds to repay flash loan plus fees
    error InsufficientFundsToRepayFlashloan();

    /// @custom:error InitiatorMismatch Invalid initiator address in flash loan callback
    error InitiatorMismatch();

    /// @custom:error OnBehalfMismatch Invalid onBehalf address in flash loan callback
    error OnBehalfMismatch();

    /// @custom:error EnterMarketFailed Comptroller.enterMarketBehalf returned a non-zero error code
    error EnterMarketFailed(uint256 err);

    /// @custom:error MarketNotListed Provided vToken market is not listed in Comptroller
    error MarketNotListed(address market);

    /// @custom:error VBNBNotSupported vBNB market is not supported for leverage operations
    error VBNBNotSupported();

    /// @custom:error ZeroAddress One of the required addresses is zero
    error ZeroAddress();

    /// @custom:error NotAnApprovedDelegate User has not approved this contract as a delegate
    error NotAnApprovedDelegate();

    /// @custom:error ZeroFlashLoanAmount Flash loan amount cannot be zero
    error ZeroFlashLoanAmount();

    /// @custom:error AccrueInterestFailed accrueInterest on a vToken market returned a non-zero error code
    error AccrueInterestFailed(uint256 errorCode);

    /// @custom:error IdenticalMarkets Collateral and borrow markets cannot be the same
    error IdenticalMarkets();

    /// @notice Emitted when dust amounts are transferred after a leverage operation
    /// @param recipient The address receiving the dust (user or protocol share reserve)
    /// @param token The underlying token address
    /// @param amount The amount of dust transferred
    event DustTransferred(address indexed recipient, address indexed token, uint256 amount);

    /// @notice Emitted when a user enters a leveraged position with single collateral asset
    /// @param user The address of the user entering the position
    /// @param collateralMarket The vToken market used as collateral
    /// @param collateralAmountSeed The initial collateral amount provided by the user
    /// @param collateralAmountToFlashLoan The amount being flash loaned
    event SingleAssetLeverageEntered(
        address indexed user,
        IVToken indexed collateralMarket,
        uint256 collateralAmountSeed,
        uint256 collateralAmountToFlashLoan
    );

    /// @notice Emitted when a user enters a leveraged position with collateral seed
    /// @param user The address of the user entering the position
    /// @param collateralMarket The vToken market used as collateral
    /// @param collateralAmountSeed The initial collateral amount provided by the user
    /// @param borrowedMarket The vToken market being borrowed from
    /// @param borrowedAmountToFlashLoan The amount being flash loaned
    event LeverageEntered(
        address indexed user,
        IVToken indexed collateralMarket,
        uint256 collateralAmountSeed,
        IVToken indexed borrowedMarket,
        uint256 borrowedAmountToFlashLoan
    );

    /// @notice Emitted when a user enters a leveraged position with borrowed asset seed
    /// @param user The address of the user entering the position
    /// @param collateralMarket The vToken market used as collateral
    /// @param borrowedMarket The vToken market being borrowed from
    /// @param borrowedAmountSeed The initial borrowed asset amount provided by the user
    /// @param borrowedAmountToFlashLoan The amount being flash loaned
    event LeverageEnteredFromBorrow(
        address indexed user,
        IVToken indexed collateralMarket,
        IVToken indexed borrowedMarket,
        uint256 borrowedAmountSeed,
        uint256 borrowedAmountToFlashLoan
    );

    /// @notice Emitted when a user exits a leveraged position
    /// @param user The address of the user exiting the position
    /// @param collateralMarket The vToken market being redeemed
    /// @param collateralAmountToRedeemForSwap The amount of collateral being redeemed for swap
    /// @param borrowedMarket The vToken market being repaid
    /// @param borrowedAmountToFlashLoan The amount being flash loaned
    event LeverageExited(
        address indexed user,
        IVToken indexed collateralMarket,
        uint256 collateralAmountToRedeemForSwap,
        IVToken indexed borrowedMarket,
        uint256 borrowedAmountToFlashLoan
    );

    /// @notice Emitted when a user exits a leveraged position with single collateral asset
    /// @param user The address of the user exiting the position
    /// @param collateralMarket The vToken market used for both collateral and borrowed asset
    /// @param collateralAmountToFlashLoan The amount being flash loaned
    event SingleAssetLeverageExited(
        address indexed user,
        IVToken indexed collateralMarket,
        uint256 collateralAmountToFlashLoan
    );

    /**
     * @notice Enumeration of operation types for flash loan callbacks
     * @param NONE Default value indicating no operation set
     * @param ENTER_SINGLE_ASSET Operation for entering a leveraged position using single asset (no swap)
     * @param ENTER_COLLATERAL Operation for entering a leveraged position with collateral seed
     * @param ENTER_BORROW Operation for entering a leveraged position with borrowed asset seed
     * @param EXIT_COLLATERAL Operation for exiting a leveraged position with swap
     * @param EXIT_SINGLE_ASSET Operation for exiting a leveraged position using single asset (no swap)
     */
    enum OperationType {
        NONE,
        ENTER_SINGLE_ASSET,
        ENTER_COLLATERAL,
        ENTER_BORROW,
        EXIT_COLLATERAL,
        EXIT_SINGLE_ASSET
    }

    /**
     * @notice Enters a leveraged position using only collateral provided by the user
     * @dev This function flash loans additional collateral assets, amplifying the user's supplied collateral
     *      in the Venus protocol. The user must have delegated permission to this contract via the comptroller.
     *      Any remaining collateral dust after the operation is returned to the user.
     * @param collateralMarket The vToken market where collateral will be supplied (must not be vBNB)
     * @param collateralAmountSeed The initial amount of collateral the user provides (can be 0)
     * @param collateralAmountToFlashLoan The amount to borrow via flash loan for leverage
     * @custom:emits SingleAssetLeverageEntered
     * @custom:error NotAnApprovedDelegate if caller has not delegated to this contract
     * @custom:error AccrueInterestFailed if interest accrual fails on the collateral market
     * @custom:error MarketNotListed if the market is not listed in Comptroller
     * @custom:error VBNBNotSupported if the market is vBNB
     * @custom:error OperationCausesLiquidation if the operation would make the account unsafe
     * @custom:error TransferFromUserFailed if seed amount transfer from user fails
     * @custom:error MintBehalfFailed if mint behalf operation fails
     * @custom:error BorrowBehalfFailed if borrow behalf operation fails
     */
    function enterSingleAssetLeverage(
        IVToken collateralMarket,
        uint256 collateralAmountSeed,
        uint256 collateralAmountToFlashLoan
    ) external;

    /**
     * @notice Enters a leveraged position by borrowing assets and converting them to collateral
     * @dev This function uses flash loans to borrow assets, swaps them for collateral tokens,
     *      and supplies the collateral to the Venus protocol to amplify the user's position.
     *      The user must have delegated permission to this contract via the comptroller.
     *      Any remaining dust (both collateral and borrowed assets) after the operation is returned to the user.
     * @param collateralMarket The vToken market where collateral will be supplied (must not be vBNB)
     * @param collateralAmountSeed The initial amount of collateral the user provides (can be 0)
     * @param borrowedMarket The vToken market from which assets will be borrowed via flash loan (must not be vBNB)
     * @param borrowedAmountToFlashLoan The amount to borrow via flash loan for leverage
     * @param minAmountOutAfterSwap The minimum amount of collateral expected after swap (for slippage protection)
     * @param swapData Bytes containing swap instructions for converting borrowed assets to collateral
     * @custom:emits LeverageEntered
     * @custom:error IdenticalMarkets if collateral and borrow markets are the same
     * @custom:error NotAnApprovedDelegate if caller has not delegated to this contract
     * @custom:error AccrueInterestFailed if interest accrual fails on any market
     * @custom:error MarketNotListed if any market is not listed in Comptroller
     * @custom:error VBNBNotSupported if collateral or borrow market is vBNB
     * @custom:error OperationCausesLiquidation if the operation would make the account unsafe
     * @custom:error TransferFromUserFailed if seed amount transfer from user fails
     * @custom:error MintBehalfFailed if mint behalf operation fails
     * @custom:error BorrowBehalfFailed if borrow behalf operation fails
     * @custom:error TokenSwapCallFailed if token swap execution fails
     * @custom:error SlippageExceeded if collateral balance after swap is below minimum
     */
    function enterLeverage(
        IVToken collateralMarket,
        uint256 collateralAmountSeed,
        IVToken borrowedMarket,
        uint256 borrowedAmountToFlashLoan,
        uint256 minAmountOutAfterSwap,
        bytes calldata swapData
    ) external;

    /**
     * @notice Enters a leveraged position by using existing borrowed assets and converting them to collateral
     * @dev This function uses flash loans to borrow additional assets, swaps the total borrowed amount
     *      for collateral tokens, and supplies the collateral to the Venus protocol to amplify the user's position.
     *      The user must have delegated permission to this contract via the comptroller.
     *      Any remaining dust (both collateral and borrowed assets) after the operation is returned to the user.
     * @param collateralMarket The vToken market where collateral will be supplied (must not be vBNB)
     * @param borrowedMarket The vToken market from which assets will be borrowed via flash loan (must not be vBNB)
     * @param borrowedAmountSeed The initial amount of borrowed assets the user provides (can be 0)
     * @param borrowedAmountToFlashLoan The additional amount to borrow via flash loan for leverage
     * @param minAmountOutAfterSwap The minimum amount of collateral expected after swap (for slippage protection)
     * @param swapData Bytes containing swap instructions for converting borrowed assets to collateral
     * @custom:emits LeverageEnteredFromBorrow
     * @custom:error IdenticalMarkets if collateral and borrow markets are the same
     * @custom:error NotAnApprovedDelegate if caller has not delegated to this contract
     * @custom:error AccrueInterestFailed if interest accrual fails on any market
     * @custom:error MarketNotListed if any market is not listed in Comptroller
     * @custom:error VBNBNotSupported if collateral or borrow market is vBNB
     * @custom:error OperationCausesLiquidation if the operation would make the account unsafe
     * @custom:error TransferFromUserFailed if seed amount transfer from user fails
     * @custom:error MintBehalfFailed if mint behalf operation fails
     * @custom:error BorrowBehalfFailed if borrow behalf operation fails
     * @custom:error TokenSwapCallFailed if token swap execution fails
     * @custom:error SlippageExceeded if collateral balance after swap is below minimum
     */
    function enterLeverageFromBorrow(
        IVToken collateralMarket,
        IVToken borrowedMarket,
        uint256 borrowedAmountSeed,
        uint256 borrowedAmountToFlashLoan,
        uint256 minAmountOutAfterSwap,
        bytes calldata swapData
    ) external;

    /**
     * @notice Exits a leveraged position by redeeming collateral and repaying borrowed assets
     * @dev This function uses flash loans to temporarily repay debt, redeems collateral,
     *      swaps collateral for borrowed assets, and repays the flash loan. Any remaining
     *      dust (both collateral and borrowed assets) is returned to the user. This ensures
     *      users who swap more than required as protection against price volatility receive
     *      their excess tokens back.
     *
     *      The flash loan amount can exceed actual debt to account for interest accrual
     *      between transaction creation and mining. The contract caps repayment to actual
     *      debt and uses leftover funds toward flash loan repayment.
     *
     *      NOTE: No pre-operation safety check is performed because exiting leverage reduces
     *      debt exposure, which can only improve account health. Post-operation safety is
     *      still validated to ensure the final position is healthy.
     *
     *      IMPORTANT: If treasuryPercent() is nonzero, the user must provide a
     *      collateralAmountToRedeemForSwap that accounts for the treasury fee. Only
     *      (1 - treasuryPercent/1e18) of the redeemed amount is transferred to this contract.
     *      Required gross amount = netAmountNeeded * 1e18 / (1e18 - treasuryPercent)
     * @param collateralMarket The vToken market from which collateral will be redeemed (must not be vBNB)
     * @param collateralAmountToRedeemForSwap The gross amount of collateral to redeem (must account for treasury fee if nonzero)
     * @param borrowedMarket The vToken market where debt will be repaid via flash loan (must not be vBNB)
     * @param borrowedAmountToFlashLoan The amount to borrow via flash loan for debt repayment (can exceed actual debt)
     * @param minAmountOutAfterSwap The minimum amount of borrowed asset expected after swap (for slippage protection)
     * @param swapData Bytes containing swap instructions for converting collateral to borrowed assets
     * @custom:emits LeverageExited
     * @custom:error IdenticalMarkets if collateral and borrow markets are the same
     * @custom:error NotAnApprovedDelegate if caller has not delegated to this contract
     * @custom:error MarketNotListed if any market is not listed in Comptroller
     * @custom:error VBNBNotSupported if collateral or borrow market is vBNB
     * @custom:error OperationCausesLiquidation if the operation would make the account unsafe
     * @custom:error RepayBehalfFailed if repay operation fails
     * @custom:error RedeemBehalfFailed if redeem operation fails
     * @custom:error TokenSwapCallFailed if token swap execution fails
     * @custom:error SlippageExceeded if swap output is below minimum required
     * @custom:error InsufficientFundsToRepayFlashloan if insufficient funds to repay flash loan
     */
    function exitLeverage(
        IVToken collateralMarket,
        uint256 collateralAmountToRedeemForSwap,
        IVToken borrowedMarket,
        uint256 borrowedAmountToFlashLoan,
        uint256 minAmountOutAfterSwap,
        bytes calldata swapData
    ) external;

    /**
     * @notice Exits a leveraged position when collateral and borrowed assets are the same token
     * @dev This function uses flash loans to temporarily repay debt, redeems collateral,
     *      and repays the flash loan without requiring token swaps. This is more gas-efficient
     *      than exitLeverage when dealing with single-asset positions. Any remaining collateral
     *      dust after the operation is returned to the user.
     *
     *      The flash loan amount can exceed actual debt to account for interest accrual
     *      between transaction creation and mining. The contract caps repayment to actual
     *      debt and uses leftover funds toward flash loan repayment.
     *
     *      If treasuryPercent() is nonzero, the contract automatically adjusts the redeem
     *      amount to ensure sufficient funds are received to repay the flash loan after the
     *      treasury fee deduction.
     *
     *      NOTE: No pre-operation safety check is performed because exiting leverage reduces
     *      debt exposure, which can only improve account health. Post-operation safety is
     *      still validated to ensure the final position is healthy.
     * @param collateralMarket The vToken market for both collateral and borrowed asset (must not be vBNB)
     * @param collateralAmountToFlashLoan The amount to borrow via flash loan for debt repayment (can exceed actual debt)
     * @custom:emits SingleAssetLeverageExited
     * @custom:error NotAnApprovedDelegate if caller has not delegated to this contract
     * @custom:error MarketNotListed if the market is not listed in Comptroller
     * @custom:error VBNBNotSupported if the market is vBNB
     * @custom:error OperationCausesLiquidation if the operation would make the account unsafe
     * @custom:error RepayBehalfFailed if repay operation fails
     * @custom:error RedeemBehalfFailed if redeem operation fails
     * @custom:error InsufficientFundsToRepayFlashloan if insufficient funds to repay flash loan
     */
    function exitSingleAssetLeverage(IVToken collateralMarket, uint256 collateralAmountToFlashLoan) external;
}

contracts/LeverageManager/LeverageStrate.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.28;

import { Ownable2StepUpgradeable } from "@openzeppelin/contracts-upgradeable/access/Ownable2StepUpgradeable.sol";
import { ReentrancyGuardUpgradeable } from "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import {
    SafeERC20Upgradeable,
    IERC20Upgradeable
} from "@openzeppelin/contracts-upgradeable/token/ERC20/utils/SafeERC20Upgradeable.sol";

import { IVToken, IComptroller, IFlashLoanReceiver } from "../Interfaces.sol";
import { SwapHelper } from "../SwapHelper/SwapHelper.sol";

import { ILeverageStrategiesManager } from "./ILeverageStrategiesManager.sol";

/**
 * @title LeverageStrategiesManager
 * @author Venus Protocol
 * @notice Contract for managing leveraged positions using flash loans and token swaps
 */
contract LeverageStrategiesManager is
    Ownable2StepUpgradeable,
    ReentrancyGuardUpgradeable,
    IFlashLoanReceiver,
    ILeverageStrategiesManager
{
    using SafeERC20Upgradeable for IERC20Upgradeable;

    /// @dev Success return value for VToken operations (mint, borrow, repay, redeem)
    uint256 private constant SUCCESS = 0;

    /// @dev Mantissa for fixed-point arithmetic (1e18 = 100%)
    uint256 private constant MANTISSA_ONE = 1e18;

    /// @notice The Venus comptroller contract for market interactions and flash loans execution
    IComptroller public immutable COMPTROLLER;

    /// @notice The swap helper contract for executing token swaps during leverage operations
    SwapHelper public immutable swapHelper;

    /// @notice The vBNB market address (not supported for leverage operations)
    IVToken public immutable vBNB;

    /// @dev Transient (EIP-1153): Cleared at transaction end. Tracks operation type during flash loan callback.
    OperationType transient operationType;

    /// @dev Transient (EIP-1153): Cleared at transaction end. Stores msg.sender for flash loan callback context.
    address transient operationInitiator;

    /// @dev Transient (EIP-1153): Cleared at transaction end. Stores collateral market for flash loan callback.
    IVToken transient collateralMarket;

    /// @dev Transient (EIP-1153): Cleared at transaction end. Stores collateral seed (enter) or redeem amount (exit).
    uint256 transient collateralAmount;

    /// @dev Transient (EIP-1153): Cleared at transaction end. Stores borrowed amount seed for enterLeverageFromBorrow.
    uint256 transient borrowedAmountSeed;

    /// @dev Transient (EIP-1153): Cleared at transaction end. Stores minimum expected output after swap.
    uint256 transient minAmountOutAfterSwap;

    /**
     * @notice Contract constructor
     * @dev Sets immutable variables and disables initializers for the implementation contract
     * @param _comptroller The Venus comptroller contract address
     * @param _swapHelper The swap helper contract address
     * @param _vBNB The vBNB market address (not supported for leverage operations)
     * @custom:oz-upgrades-unsafe-allow constructor
     */
    constructor(IComptroller _comptroller, SwapHelper _swapHelper, IVToken _vBNB) {
        if (address(_comptroller) == address(0) || address(_swapHelper) == address(0) || address(_vBNB) == address(0)) {
            revert ZeroAddress();
        }

        COMPTROLLER = _comptroller;
        swapHelper = _swapHelper;
        vBNB = _vBNB;
        _disableInitializers();
    }

    /**
     * @notice Initializes the contract
     * @dev Sets up the Ownable2Step functionality. Can only be called once.
     */
    function initialize() external initializer {
        __Ownable2Step_init();
        __ReentrancyGuard_init();
    }

    /// @inheritdoc ILeverageStrategiesManager
    function enterSingleAssetLeverage(
        IVToken _collateralMarket,
        uint256 _collateralAmountSeed,
        uint256 _collateralAmountToFlashLoan
    ) external {
        if (_collateralAmountToFlashLoan == 0) revert ZeroFlashLoanAmount();
        _checkMarketSupported(_collateralMarket);

        _checkUserDelegated();

        _accrueInterest(_collateralMarket);

        _validateAndEnterMarket(msg.sender, _collateralMarket);
        _checkAccountSafe(msg.sender);

        _transferSeedAmountFromUser(_collateralMarket, msg.sender, _collateralAmountSeed);

        operationInitiator = msg.sender;
        operationType = OperationType.ENTER_SINGLE_ASSET;
        collateralAmount = _collateralAmountSeed;

        IVToken[] memory borrowedMarkets = new IVToken[](1);
        borrowedMarkets[0] = _collateralMarket;
        uint256[] memory flashLoanAmounts = new uint256[](1);
        flashLoanAmounts[0] = _collateralAmountToFlashLoan;

        COMPTROLLER.executeFlashLoan(
            payable(msg.sender),
            payable(address(this)),
            borrowedMarkets,
            flashLoanAmounts,
            ""
        );

        _checkAccountSafe(msg.sender);

        emit SingleAssetLeverageEntered(
            msg.sender,
            _collateralMarket,
            _collateralAmountSeed,
            _collateralAmountToFlashLoan
        );

        _transferDustToInitiator(_collateralMarket);
    }

    /// @inheritdoc ILeverageStrategiesManager
    function enterLeverage(
        IVToken _collateralMarket,
        uint256 _collateralAmountSeed,
        IVToken _borrowedMarket,
        uint256 _borrowedAmountToFlashLoan,
        uint256 _minAmountOutAfterSwap,
        bytes calldata _swapData
    ) external {
        if (_borrowedAmountToFlashLoan == 0) revert ZeroFlashLoanAmount();
        if (_collateralMarket == _borrowedMarket) revert IdenticalMarkets();
        _checkMarketSupported(_collateralMarket);
        _checkMarketSupported(_borrowedMarket);

        _checkUserDelegated();

        _accrueInterest(_collateralMarket);
        _accrueInterest(_borrowedMarket);

        _validateAndEnterMarket(msg.sender, _collateralMarket);
        _checkAccountSafe(msg.sender);

        _transferSeedAmountFromUser(_collateralMarket, msg.sender, _collateralAmountSeed);

        operationInitiator = msg.sender;
        collateralMarket = _collateralMarket;
        collateralAmount = _collateralAmountSeed;
        minAmountOutAfterSwap = _minAmountOutAfterSwap;
        operationType = OperationType.ENTER_COLLATERAL;

        IVToken[] memory borrowedMarkets = new IVToken[](1);
        borrowedMarkets[0] = _borrowedMarket;
        uint256[] memory flashLoanAmounts = new uint256[](1);
        flashLoanAmounts[0] = _borrowedAmountToFlashLoan;

        COMPTROLLER.executeFlashLoan(
            payable(msg.sender),
            payable(address(this)),
            borrowedMarkets,
            flashLoanAmounts,
            _swapData
        );

        _checkAccountSafe(msg.sender);

        emit LeverageEntered(
            msg.sender,
            _collateralMarket,
            _collateralAmountSeed,
            _borrowedMarket,
            _borrowedAmountToFlashLoan
        );

        _transferDustToInitiator(_collateralMarket);
        _transferDustToInitiator(_borrowedMarket);
    }

    /// @inheritdoc ILeverageStrategiesManager
    function enterLeverageFromBorrow(
        IVToken _collateralMarket,
        IVToken _borrowedMarket,
        uint256 _borrowedAmountSeed,
        uint256 _borrowedAmountToFlashLoan,
        uint256 _minAmountOutAfterSwap,
        bytes calldata _swapData
    ) external {
        if (_borrowedAmountToFlashLoan == 0) revert ZeroFlashLoanAmount();
        if (_collateralMarket == _borrowedMarket) revert IdenticalMarkets();
        _checkMarketSupported(_collateralMarket);
        _checkMarketSupported(_borrowedMarket);

        _checkUserDelegated();

        _accrueInterest(_collateralMarket);
        _accrueInterest(_borrowedMarket);

        _validateAndEnterMarket(msg.sender, _collateralMarket);
        _checkAccountSafe(msg.sender);

        _transferSeedAmountFromUser(_borrowedMarket, msg.sender, _borrowedAmountSeed);

        operationInitiator = msg.sender;
        collateralMarket = _collateralMarket;
        borrowedAmountSeed = _borrowedAmountSeed;
        minAmountOutAfterSwap = _minAmountOutAfterSwap;
        operationType = OperationType.ENTER_BORROW;

        IVToken[] memory borrowedMarkets = new IVToken[](1);
        borrowedMarkets[0] = _borrowedMarket;
        uint256[] memory flashLoanAmounts = new uint256[](1);
        flashLoanAmounts[0] = _borrowedAmountToFlashLoan;

        COMPTROLLER.executeFlashLoan(
            payable(msg.sender),
            payable(address(this)),
            borrowedMarkets,
            flashLoanAmounts,
            _swapData
        );

        _checkAccountSafe(msg.sender);

        emit LeverageEnteredFromBorrow(
            msg.sender,
            _collateralMarket,
            _borrowedMarket,
            _borrowedAmountSeed,
            _borrowedAmountToFlashLoan
        );

        _transferDustToInitiator(_collateralMarket);
        _transferDustToInitiator(_borrowedMarket);
    }

    /// @inheritdoc ILeverageStrategiesManager
    function exitLeverage(
        IVToken _collateralMarket,
        uint256 _collateralAmountToRedeemForSwap,
        IVToken _borrowedMarket,
        uint256 _borrowedAmountToFlashLoan,
        uint256 _minAmountOutAfterSwap,
        bytes calldata _swapData
    ) external {
        if (_borrowedAmountToFlashLoan == 0) revert ZeroFlashLoanAmount();
        if (_collateralMarket == _borrowedMarket) revert IdenticalMarkets();
        _checkMarketSupported(_collateralMarket);
        _checkMarketSupported(_borrowedMarket);

        _checkUserDelegated();

        operationInitiator = msg.sender;
        collateralMarket = _collateralMarket;
        collateralAmount = _collateralAmountToRedeemForSwap;
        minAmountOutAfterSwap = _minAmountOutAfterSwap;
        operationType = OperationType.EXIT_COLLATERAL;

        IVToken[] memory borrowedMarkets = new IVToken[](1);
        borrowedMarkets[0] = _borrowedMarket;
        uint256[] memory flashLoanAmounts = new uint256[](1);
        flashLoanAmounts[0] = _borrowedAmountToFlashLoan;

        COMPTROLLER.executeFlashLoan(
            payable(msg.sender),
            payable(address(this)),
            borrowedMarkets,
            flashLoanAmounts,
            _swapData
        );

        _checkAccountSafe(msg.sender);

        emit LeverageExited(
            msg.sender,
            _collateralMarket,
            _collateralAmountToRedeemForSwap,
            _borrowedMarket,
            _borrowedAmountToFlashLoan
        );

        _transferDustToInitiator(_collateralMarket);
        _transferDustToInitiator(_borrowedMarket);
    }

    /// @inheritdoc ILeverageStrategiesManager
    function exitSingleAssetLeverage(IVToken _collateralMarket, uint256 _collateralAmountToFlashLoan) external {
        if (_collateralAmountToFlashLoan == 0) revert ZeroFlashLoanAmount();
        _checkMarketSupported(_collateralMarket);
        _checkUserDelegated();

        operationInitiator = msg.sender;
        collateralMarket = _collateralMarket;
        operationType = OperationType.EXIT_SINGLE_ASSET;

        IVToken[] memory borrowedMarkets = new IVToken[](1);
        borrowedMarkets[0] = _collateralMarket;
        uint256[] memory flashLoanAmounts = new uint256[](1);
        flashLoanAmounts[0] = _collateralAmountToFlashLoan;

        COMPTROLLER.executeFlashLoan(
            payable(msg.sender),
            payable(address(this)),
            borrowedMarkets,
            flashLoanAmounts,
            ""
        );

        _checkAccountSafe(msg.sender);

        emit SingleAssetLeverageExited(msg.sender, _collateralMarket, _collateralAmountToFlashLoan);

        _transferDustToInitiator(_collateralMarket);
    }

    /**
     * @notice Flash loan callback entrypoint called by Comptroller
     * @dev Protected by nonReentrant modifier to prevent reentrancy attacks during flash loan execution
     * @param vTokens Array with the borrowed vToken market (single element)
     * @param amounts Array with the borrowed underlying amount (single element)
     * @param premiums Array with the flash loan fee amount (single element)
     * @param initiator The address that initiated the flash loan (must be this contract)
     * @param onBehalf The user for whom debt will be opened
     * @param param Encoded auxiliary data for the operation (e.g., swap multicall)
     * @return success Whether the execution succeeded
     * @return repayAmounts Amounts to approve for flash loan repayment
     * @custom:error InitiatorMismatch When initiator is not this contract
     * @custom:error OnBehalfMismatch When onBehalf is not the operation initiator
     * @custom:error UnauthorizedExecutor When caller is not the Comptroller
     * @custom:error FlashLoanAssetOrAmountMismatch When array lengths mismatch or > 1 element
     * @custom:error InvalidExecuteOperation When operation type is unknown
     */
    function executeOperation(
        IVToken[] calldata vTokens,
        uint256[] calldata amounts,
        uint256[] calldata premiums,
        address initiator,
        address onBehalf,
        bytes calldata param
    ) external override nonReentrant returns (bool success, uint256[] memory repayAmounts) {
        // Only the Comptroller can invoke this callback during flash loan execution
        if (msg.sender != address(COMPTROLLER)) {
            revert UnauthorizedExecutor();
        }

        // Flash loan must be initiated by this contract to prevent unauthorized callbacks
        if (initiator != address(this)) {
            revert InitiatorMismatch();
        }

        // The flash loan beneficiary must match the user who called the entry function
        if (onBehalf != operationInitiator) {
            revert OnBehalfMismatch();
        }

        // This contract only supports single-market flash loans
        if (vTokens.length != 1 || amounts.length != 1 || premiums.length != 1) {
            revert FlashLoanAssetOrAmountMismatch();
        }

        repayAmounts = new uint256[](1);
        if (operationType == OperationType.ENTER_SINGLE_ASSET) {
            repayAmounts[0] = _handleEnterSingleAsset(onBehalf, vTokens[0], amounts[0], premiums[0]);
        } else if (operationType == OperationType.ENTER_COLLATERAL) {
            repayAmounts[0] = _handleEnterCollateral(onBehalf, vTokens[0], amounts[0], premiums[0], param);
        } else if (operationType == OperationType.ENTER_BORROW) {
            repayAmounts[0] = _handleEnterBorrow(onBehalf, vTokens[0], amounts[0], premiums[0], param);
        } else if (operationType == OperationType.EXIT_COLLATERAL) {
            repayAmounts[0] = _handleExitCollateral(onBehalf, vTokens[0], amounts[0], premiums[0], param);
        } else if (operationType == OperationType.EXIT_SINGLE_ASSET) {
            repayAmounts[0] = _handleExitSingleAsset(onBehalf, vTokens[0], amounts[0], premiums[0]);
        } else {
            revert InvalidExecuteOperation();
        }

        return (true, repayAmounts);
    }

    /**
     * @notice Executes the enter leveraged position with single collateral operation during flash loan callback
     * @dev This function performs the following steps:
     *      1. Combines flash loaned collateral with user's seed collateral
     *      2. Supplies all collateral to the Venus market on behalf of the user
     *      3. Borrows the repayment amount (fees) on behalf of the user
     *      4. Approves the collateral asset for repayment to the flash loan
     * @param onBehalf Address on whose behalf the operation is performed
     * @param market The vToken market for the collateral asset
     * @param flashloanedCollateralAmount The amount of collateral assets received from flash loan
     * @param collateralAmountFees The fees to be paid on the flash loaned collateral amount
     * @return flashLoanRepayAmount The total amount of collateral assets to repay (fees only)
     * @custom:error MintBehalfFailed if mint behalf operation fails
     * @custom:error BorrowBehalfFailed if borrow behalf operation fails
     * @custom:error InsufficientFundsToRepayFlashloan if insufficient funds are available to repay the flash loan
     */
    function _handleEnterSingleAsset(
        address onBehalf,
        IVToken market,
        uint256 flashloanedCollateralAmount,
        uint256 collateralAmountFees
    ) internal returns (uint256 flashLoanRepayAmount) {
        IERC20Upgradeable collateralAsset = IERC20Upgradeable(market.underlying());

        uint256 totalCollateralAmountToMint = flashloanedCollateralAmount + collateralAmount;
        collateralAsset.forceApprove(address(market), totalCollateralAmountToMint);

        uint256 err = market.mintBehalf(onBehalf, totalCollateralAmountToMint);
        if (err != SUCCESS) {
            revert MintBehalfFailed(err);
        }

        flashLoanRepayAmount = _borrowAndRepayFlashLoanFee(onBehalf, market, collateralAsset, collateralAmountFees);
    }

    /**
     * @notice Executes the enter leveraged position operation during flash loan callback
     * @dev This function performs the following steps:
     *      1. Swaps flash loaned borrowed assets for collateral assets
     *      2. Supplies all collateral received from swap plus seed to the Venus market on behalf of the user
     *      3. Borrows the repayment amount on behalf of the user
     *      4. Approves the borrowed asset for repayment to the flash loan
     * @param onBehalf Address on whose behalf the operation is performed
     * @param borrowMarket The vToken market from which assets were borrowed
     * @param borrowedAssetAmount The amount of borrowed assets received from flash loan
     * @param borrowedAssetFees The fees to be paid on the borrowed asset amount
     * @param swapCallData The encoded swap instructions for converting borrowed to collateral assets
     * @return flashLoanRepayAmount The total amount of borrowed assets to repay (fees only)
     * @custom:error MintBehalfFailed if mint behalf operation fails
     * @custom:error BorrowBehalfFailed if borrow behalf operation fails
     * @custom:error TokenSwapCallFailed if token swap execution fails
     * @custom:error SlippageExceeded if collateral balance after swap is below minimum
     */
    function _handleEnterCollateral(
        address onBehalf,
        IVToken borrowMarket,
        uint256 borrowedAssetAmount,
        uint256 borrowedAssetFees,
        bytes calldata swapCallData
    ) internal returns (uint256 flashLoanRepayAmount) {
        IERC20Upgradeable borrowedAsset = IERC20Upgradeable(borrowMarket.underlying());

        // Cache transient storage reads for variables used more than once to save gas
        IVToken _collateralMarket = collateralMarket;
        uint256 _minAmountOutAfterSwap = minAmountOutAfterSwap;

        IERC20Upgradeable collateralAsset = IERC20Upgradeable(_collateralMarket.underlying());
        uint256 swappedCollateralAmountOut = _performSwap(
            borrowedAsset,
            borrowedAssetAmount,
            collateralAsset,
            _minAmountOutAfterSwap,
            swapCallData
        );

        uint256 collateralAmountToMint = swappedCollateralAmountOut + collateralAmount;
        collateralAsset.forceApprove(address(_collateralMarket), collateralAmountToMint);

        uint256 err = _collateralMarket.mintBehalf(onBehalf, collateralAmountToMint);
        if (err != SUCCESS) {
            revert MintBehalfFailed(err);
        }

        flashLoanRepayAmount = _borrowAndRepayFlashLoanFee(onBehalf, borrowMarket, borrowedAsset, borrowedAssetFees);
    }

    /**
     * @notice Executes the enter leveraged position with borrowed assets operation during flash loan callback
     * @dev This function performs the following steps:
     *      1. Swaps the total borrowed assets (seed + flash loan) for collateral assets
     *      2. Supplies all collateral received from swap to the Venus market on behalf of the user
     *      3. Borrows the repayment amount on behalf of the user
     *      4. Approves the borrowed asset for repayment to the flash loan
     * @param onBehalf Address on whose behalf the operation is performed
     * @param borrowMarket The vToken market from which assets were borrowed
     * @param borrowedAssetAmount The amount of borrowed assets received from flash loan
     * @param borrowedAssetFees The fees to be paid on the borrowed asset amount
     * @param swapCallData The encoded swap instructions for converting borrowed to collateral assets
     * @return flashLoanRepayAmount The total amount of borrowed assets to repay (fees only)
     * @custom:error MintBehalfFailed if mint behalf operation fails
     * @custom:error BorrowBehalfFailed if borrow behalf operation fails
     * @custom:error TokenSwapCallFailed if token swap execution fails
     * @custom:error SlippageExceeded if collateral balance after swap is below minimum
     */
    function _handleEnterBorrow(
        address onBehalf,
        IVToken borrowMarket,
        uint256 borrowedAssetAmount,
        uint256 borrowedAssetFees,
        bytes calldata swapCallData
    ) internal returns (uint256 flashLoanRepayAmount) {
        IERC20Upgradeable borrowedAsset = IERC20Upgradeable(borrowMarket.underlying());

        // Cache transient storage reads for variables used more than once to save gas
        IVToken _collateralMarket = collateralMarket;
        uint256 _minAmountOutAfterSwap = minAmountOutAfterSwap;

        IERC20Upgradeable collateralAsset = IERC20Upgradeable(_collateralMarket.underlying());

        uint256 totalBorrowedAmountToSwap = borrowedAmountSeed + borrowedAssetAmount;

        uint256 swappedCollateralAmountOut = _performSwap(
            borrowedAsset,
            totalBorrowedAmountToSwap,
            collateralAsset,
            _minAmountOutAfterSwap,
            swapCallData
        );

        collateralAsset.forceApprove(address(_collateralMarket), swappedCollateralAmountOut);

        uint256 err = _collateralMarket.mintBehalf(onBehalf, swappedCollateralAmountOut);
        if (err != SUCCESS) {
            revert MintBehalfFailed(err);
        }

        flashLoanRepayAmount = _borrowAndRepayFlashLoanFee(onBehalf, borrowMarket, borrowedAsset, borrowedAssetFees);
    }

    /**
     * @notice Executes the exit leveraged position operation during flash loan callback
     * @dev This function performs the following steps:
     *      1. Queries actual debt and caps repayment to min(flashLoanAmount, actualDebt)
     *         to handle cases where UI flash loans slightly more than current debt
     *      2. Repays user's debt (up to actual debt amount) in the borrowed market
     *      3. Calculates redeem amount accounting for treasury fee (if any)
     *      4. Redeems specified amount of collateral from the Venus market
     *      5. Swaps actual received collateral (after treasury fee) for borrowed assets
     *      6. Validates total borrowed asset balance (swap output + excess flash loan funds)
     *         is sufficient to repay flash loan, then approves repayment
     *
     * @param onBehalf Address on whose behalf the operation is performed
     * @param borrowMarket The vToken market from which assets were borrowed via flash loan
     * @param borrowedAssetAmountToRepayFromFlashLoan The amount borrowed via flash loan for debt repayment
     * @param borrowedAssetFees The fees to be paid on the borrowed asset amount
     * @param swapCallData The encoded swap instructions for converting collateral to borrowed assets
     * @return flashLoanRepayAmount The total amount of borrowed assets to repay
     * @custom:error RepayBehalfFailed if repayment of borrowed assets fails
     * @custom:error RedeemBehalfFailed if redeem operations fail
     * @custom:error TokenSwapCallFailed if token swap execution fails
     * @custom:error SlippageExceeded if swap output is below minimum required
     * @custom:error InsufficientFundsToRepayFlashloan if insufficient funds are available to repay the flash loan
     */
    function _handleExitCollateral(
        address onBehalf,
        IVToken borrowMarket,
        uint256 borrowedAssetAmountToRepayFromFlashLoan,
        uint256 borrowedAssetFees,
        bytes calldata swapCallData
    ) internal returns (uint256 flashLoanRepayAmount) {
        IERC20Upgradeable borrowedAsset = IERC20Upgradeable(borrowMarket.underlying());

        {
            uint256 borrowedTotalDebtAmount = borrowMarket.borrowBalanceCurrent(onBehalf);
            uint256 repayAmount = borrowedAssetAmountToRepayFromFlashLoan > borrowedTotalDebtAmount
                ? borrowedTotalDebtAmount
                : borrowedAssetAmountToRepayFromFlashLoan;

            borrowedAsset.forceApprove(address(borrowMarket), repayAmount);
            uint256 err = borrowMarket.repayBorrowBehalf(onBehalf, repayAmount);

            if (err != SUCCESS) {
                revert RepayBehalfFailed(err);
            }
        }

        // Cache transient storage reads for variables used more than once to save gas
        IVToken _collateralMarket = collateralMarket;
        uint256 collateralAmountToRedeem = collateralAmount;

        {
            uint256 treasuryPercent = COMPTROLLER.treasuryPercent();
            uint256 redeemAmount = treasuryPercent > 0
                ? (collateralAmountToRedeem * MANTISSA_ONE + (MANTISSA_ONE - treasuryPercent) - 1) /
                    (MANTISSA_ONE - treasuryPercent)
                : collateralAmountToRedeem;

            uint256 err = _collateralMarket.redeemUnderlyingBehalf(onBehalf, redeemAmount);
            if (err != SUCCESS) {
                revert RedeemBehalfFailed(err);
            }
        }

        IERC20Upgradeable collateralAsset = IERC20Upgradeable(_collateralMarket.underlying());

        _performSwap(
            collateralAsset,
            collateralAsset.balanceOf(address(this)),
            borrowedAsset,
            minAmountOutAfterSwap,
            swapCallData
        );

        flashLoanRepayAmount = borrowedAssetAmountToRepayFromFlashLoan + borrowedAssetFees;

        if (borrowedAsset.balanceOf(address(this)) < flashLoanRepayAmount) {
            revert InsufficientFundsToRepayFlashloan();
        }

        borrowedAsset.forceApprove(address(borrowMarket), flashLoanRepayAmount);
    }

    /**
     * @notice Executes the exit leveraged position with single collateral operation during flash loan callback
     * @dev This function performs the following steps:
     *      1. Queries actual debt and caps repayment to min(flashLoanAmount, actualDebt)
     *         to handle cases where UI flash loans slightly more than current debt
     *      2. Repays user's debt (up to actual debt amount) in the market
     *      3. Calculates redeem amount accounting for treasury fee (if any)
     *      4. Caps redeem amount to user's actual collateral balance to prevent revert
     *         when user entered with zero seed (collateral equals borrowed amount)
     *      5. Redeems collateral (up to user's balance) to repay flash loan
     *      6. Approves the collateral asset for repayment to the flash loan
     * @param onBehalf Address on whose behalf the operation is performed
     * @param market The vToken market for both collateral and borrowed assets
     * @param flashloanedCollateralAmount The amount borrowed via flash loan for debt repayment
     * @param collateralAmountFees The fees to be paid on the flash loaned collateral amount
     * @return flashLoanRepayAmount The total amount of collateral assets to repay
     * @custom:error RepayBehalfFailed if repayment of borrowed assets fails
     * @custom:error RedeemBehalfFailed if redeem operations fail
     * @custom:error InsufficientFundsToRepayFlashloan if insufficient funds are available to repay the flash loan
     */
    function _handleExitSingleAsset(
        address onBehalf,
        IVToken market,
        uint256 flashloanedCollateralAmount,
        uint256 collateralAmountFees
    ) internal returns (uint256 flashLoanRepayAmount) {
        IERC20Upgradeable collateralAsset = IERC20Upgradeable(market.underlying());

        uint256 marketTotalDebtAmount = market.borrowBalanceCurrent(onBehalf);
        uint256 repayAmount = flashloanedCollateralAmount > marketTotalDebtAmount
            ? marketTotalDebtAmount
            : flashloanedCollateralAmount;

        collateralAsset.forceApprove(address(market), repayAmount);
        uint256 err = market.repayBorrowBehalf(onBehalf, repayAmount);

        if (err != SUCCESS) {
            revert RepayBehalfFailed(err);
        }

        flashLoanRepayAmount = flashloanedCollateralAmount + collateralAmountFees;

        uint256 treasuryPercent = COMPTROLLER.treasuryPercent();
        uint256 redeemAmount = treasuryPercent > 0
            ? (flashLoanRepayAmount * MANTISSA_ONE + (MANTISSA_ONE - treasuryPercent) - 1) /
                (MANTISSA_ONE - treasuryPercent)
            : flashLoanRepayAmount;

        uint256 userCollateralBalance = market.balanceOfUnderlying(onBehalf);
        if (redeemAmount > userCollateralBalance) {
            redeemAmount = userCollateralBalance;
        }

        err = market.redeemUnderlyingBehalf(onBehalf, redeemAmount);
        if (err != SUCCESS) {
            revert RedeemBehalfFailed(err);
        }

        if (collateralAsset.balanceOf(address(this)) < flashLoanRepayAmount) {
            revert InsufficientFundsToRepayFlashloan();
        }

        collateralAsset.forceApprove(address(market), flashLoanRepayAmount);
    }

    /**
     * @notice Performs token swap via the SwapHelper contract
     * @dev Transfers tokens to SwapHelper and executes the swap operation.
     *      The swap operation is expected to return the output tokens to this contract.
     * @param tokenIn The input token to be swapped
     * @param amountIn The amount of input tokens to swap
     * @param tokenOut The output token to receive from the swap
     * @param minAmountOut The minimum acceptable amount of output tokens
     * @param param The encoded swap instructions/calldata for the SwapHelper
     * @return amountOut The actual amount of output tokens received from the swap
     * @custom:error TokenSwapCallFailed if the swap execution fails
     * @custom:error SlippageExceeded if the swap output is below the minimum required
     */
    function _performSwap(
        IERC20Upgradeable tokenIn,
        uint256 amountIn,
        IERC20Upgradeable tokenOut,
        uint256 minAmountOut,
        bytes calldata param
    ) internal returns (uint256 amountOut) {
        tokenIn.safeTransfer(address(swapHelper), amountIn);

        uint256 tokenOutBalanceBefore = tokenOut.balanceOf(address(this));

        (bool success, ) = address(swapHelper).call(param);
        if (!success) {
            revert TokenSwapCallFailed();
        }

        uint256 tokenOutBalanceAfter = tokenOut.balanceOf(address(this));

        amountOut = tokenOutBalanceAfter - tokenOutBalanceBefore;
        if (amountOut < minAmountOut) {
            revert SlippageExceeded();
        }

        return amountOut;
    }

    /**
     * @notice Transfers tokens from the user to this contract if amount > 0
     * @dev If the specified amount is greater than zero, transfers tokens from the user.
     *      Reverts if the actual transferred amount does not match the expected amount.
     * @param market The vToken market whose underlying asset is to be transferred
     * @param user The address of the user to transfer tokens from
     * @param amount The amount of tokens to transfer
     * @custom:error TransferFromUserFailed if the transferred amount does not match the expected amount
     */
    function _transferSeedAmountFromUser(IVToken market, address user, uint256 amount) internal {
        if (amount > 0) {
            IERC20Upgradeable token = IERC20Upgradeable(market.underlying());
            token.safeTransferFrom(user, address(this), amount);
        }
    }

    /**
     * @notice Transfers any remaining dust amounts back to the operation initiator
     * @dev This function returns small remaining balances to the user who initiated the operation.
     *      Should be called after leverage operations to ensure no funds are left in the contract.
     * @param market The vToken market whose underlying asset dust should be transferred
     */
    function _transferDustToInitiator(IVToken market) internal {
        IERC20Upgradeable asset = IERC20Upgradeable(market.underlying());

        uint256 dustAmount = asset.balanceOf(address(this));
        if (dustAmount > 0) {
            // Cache transient storage read to save gas
            address _operationInitiator = operationInitiator;
            asset.safeTransfer(_operationInitiator, dustAmount);
            emit DustTransferred(_operationInitiator, address(asset), dustAmount);
        }
    }

    /**
     * @notice Borrows assets on behalf of the user to repay the flash loan fee
     * @dev Borrows the total amount needed to repay the flash loan fee
     *      and approves the borrowed asset for repayment to the flash loan.
     * @param onBehalf Address on whose behalf assets will be borrowed
     * @param borrowMarket The vToken market from which assets will be borrowed
     * @param borrowedAsset The underlying asset being borrowed
     * @param borrowedAssetFees The fees to be paid on the borrowed asset amount
     * @return flashLoanRepayAmount The total amount of borrowed assets to repay (only fees)
     * @custom:error BorrowBehalfFailed if borrow behalf operation fails
     * @custom:error InsufficientFundsToRepayFlashloan if insufficient funds are available to repay the flash loan
     */
    function _borrowAndRepayFlashLoanFee(
        address onBehalf,
        IVToken borrowMarket,
        IERC20Upgradeable borrowedAsset,
        uint256 borrowedAssetFees
    ) internal returns (uint256 flashLoanRepayAmount) {
        flashLoanRepayAmount = borrowedAssetFees;

        uint256 marketBalanceBeforeBorrow = borrowedAsset.balanceOf(address(borrowMarket));
        uint256 err = borrowMarket.borrowBehalf(onBehalf, flashLoanRepayAmount);
        if (err != SUCCESS) {
            revert BorrowBehalfFailed(err);
        }
        uint256 marketBalanceAfterBorrow = borrowedAsset.balanceOf(address(borrowMarket));

        if (marketBalanceBeforeBorrow - marketBalanceAfterBorrow < flashLoanRepayAmount) {
            revert InsufficientFundsToRepayFlashloan();
        }

        borrowedAsset.forceApprove(address(borrowMarket), flashLoanRepayAmount);
    }

    /**
     * @notice Accrues interest on a vToken market
     * @dev Must be called before safety checks to ensure borrow balances reflect accumulated interest
     * @param market The vToken market to accrue interest on
     * @custom:error AccrueInterestFailed if the accrueInterest call returns a non-zero error code
     */
    function _accrueInterest(IVToken market) internal {
        uint256 err = market.accrueInterest();
        if (err != SUCCESS) revert AccrueInterestFailed(err);
    }

    /**
     * @notice Ensures the user has entered the market before operations
     * @dev If user is not a member of market the function calls Comptroller to enter market on behalf of user
     * @param user The account for which membership is validated/updated
     * @param market The vToken market the user must enter
     * @custom:error EnterMarketFailed when Comptroller.enterMarketBehalf returns a non-zero error code
     */
    function _validateAndEnterMarket(address user, IVToken market) internal {
        if (!COMPTROLLER.checkMembership(user, market)) {
            uint256 err = COMPTROLLER.enterMarketBehalf(user, address(market));
            if (err != SUCCESS) revert EnterMarketFailed(err);
        }
    }

    /**
     * @notice Checks if the caller has delegated this contract in the Comptroller
     * @custom:error NotAnApprovedDelegate if caller has not approved this contract as delegate
     */
    function _checkUserDelegated() internal view {
        if (!COMPTROLLER.approvedDelegates(msg.sender, address(this))) {
            revert NotAnApprovedDelegate();
        }
    }

    /**
     * @notice Checks if a `user` account is safe from liquidation
     * @dev Verifies that the user's account has no liquidity shortfall and the comptroller
     *      returned no errors when calculating account liquidity. This ensures the account
     *      won't be immediately liquidatable after the leverage operation.
     * @param user The address to check account safety for
     * @custom:error OperationCausesLiquidation if the account has a liquidity shortfall or comptroller error
     */
    function _checkAccountSafe(address user) internal view {
        (uint256 err, , uint256 shortfall) = COMPTROLLER.getBorrowingPower(user);
        if (err != SUCCESS || shortfall > 0) revert OperationCausesLiquidation(err);
    }

    /**
     * @notice Ensures that the given market is supported for leverage operations
     * @dev A market must be listed in the Comptroller and must not be vBNB.
     *      vBNB is excluded because it uses native BNB which requires special handling
     *      that this contract does not support.
     * @param market The vToken address to validate
     * @custom:error MarketNotListed if the market is not listed in Comptroller
     * @custom:error VBNBNotSupported if the market is vBNB
     */
    function _checkMarketSupported(IVToken market) internal view {
        (bool isMarketListed, , ) = COMPTROLLER.markets(address(market));
        if (!isMarketListed) revert MarketNotListed(address(market));
        if (market == vBNB) revert VBNBNotSupported();
    }
}

contracts/RelativePositionManager/IPosit.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.28;

import { IComptroller, IVToken } from "../Interfaces.sol";

/**
 * @title IPositionAccount
 * @author Venus Protocol
 * @notice Interface for Position Account contracts
 * @dev Minimal proxy contracts that hold user funds and execute operations on behalf of users
 *      in the Venus protocol. These contracts are deployed deterministically using clones.
 */
interface IPositionAccount {
    /**
     * @notice Initializes a new position account clone
     * @dev Can only be called once per clone. Sets the owner, long/short vTokens, and delegates to manager.
     * @param owner_ Address of the position account owner
     * @param longVToken_ Address of the long market vToken
     * @param shortVToken_ Address of the short market vToken
     */
    function initialize(address owner_, address longVToken_, address shortVToken_) external;

    /**
     * @notice Forwards enterLeverage to the LeverageStrategiesManager on behalf of this position account
     * @dev Only callable by the RelativePositionManager. Ensures the position account is msg.sender to LM.
     * @param collateralMarket Collateral (e.g. long) vToken to supply after swap
     * @param collateralAmountSeed Optional seed amount of collateral (RPM uses 0; collateral from swap)
     * @param borrowedMarket Borrowed (e.g. short) vToken to flash-borrow
     * @param borrowedAmountToFlashLoan Amount to borrow via flash loan
     * @param minAmountOutAfterSwap Minimum collateral out after swap (slippage protection)
     * @param swapData Swap calldata (e.g. borrowed → collateral)
     */
    function enterLeverage(
        IVToken collateralMarket,
        uint256 collateralAmountSeed,
        IVToken borrowedMarket,
        uint256 borrowedAmountToFlashLoan,
        uint256 minAmountOutAfterSwap,
        bytes calldata swapData
    ) external;

    /**
     * @notice Forwards exitLeverage to the LeverageStrategiesManager on behalf of this position account
     * @dev Only callable by the RelativePositionManager. Enables clearer flow and better revert messages.
     * @param collateralMarket Collateral (e.g. long) vToken to redeem
     * @param collateralAmountToRedeemForSwap Amount of collateral to redeem for swap
     * @param borrowedMarket Borrowed (e.g. short) vToken to repay
     * @param borrowedAmountToFlashLoan Amount to repay via flash loan
     * @param minAmountOutAfterSwap Minimum amount out after swap (slippage protection)
     * @param swapData Swap calldata (e.g. collateral → borrowed)
     */
    function exitLeverage(
        IVToken collateralMarket,
        uint256 collateralAmountToRedeemForSwap,
        IVToken borrowedMarket,
        uint256 borrowedAmountToFlashLoan,
        uint256 minAmountOutAfterSwap,
        bytes calldata swapData
    ) external;

    /**
     * @notice Forwards exitSingleAssetLeverage to the LeverageStrategiesManager (collateral and debt are same asset)
     * @dev Only callable by the RelativePositionManager. Use when DSA == short: repay short debt by redeeming DSA vTokens, no swap.
     * @param collateralMarket vToken market for both collateral and debt (e.g. DSA when DSA == short)
     * @param collateralAmountToFlashLoan Amount to borrow via flash loan for debt repayment
     */
    function exitSingleAssetLeverage(IVToken collateralMarket, uint256 collateralAmountToFlashLoan) external;

    /**
     * @notice Transfers full balance of an ERC20 token from this position account to its owner (dust recovery)
     * @dev Only callable by the RelativePositionManager. Used to sweep dust to the position owner.
     * @param token Address of the ERC20 token to transfer
     */
    function transferDustToOwner(address token) external;

    /**
     * @notice Executes multiple generic calls to external contracts on behalf of the position account
     * @dev Only callable by the authorized RelativePositionManager contract.
     * @param targets Array of target contract addresses
     * @param data Array of encoded function call data
     */
    function genericCalls(address[] calldata targets, bytes[] calldata data) external;

    /**
     * @notice Gets the Comptroller contract
     * @return Address of the Venus Comptroller
     */
    function COMPTROLLER() external view returns (IComptroller);

    /**
     * @notice Gets the authorized RelativePositionManager contract
     * @return Address of the RelativePositionManager contract
     */
    function RELATIVE_POSITION_MANAGER() external view returns (address);

    /**
     * @notice Gets the LeverageStrategiesManager contract
     * @return Address of the LeverageStrategiesManager contract
     */
    function LEVERAGE_MANAGER() external view returns (address);

    /**
     * @notice Gets the owner of this position account
     * @return owner Address of the position account owner
     */
    function owner() external view returns (address owner);

    /**
     * @notice Gets the long vToken for this position
     * @return longVToken Address of the long market vToken
     */
    function longVToken() external view returns (address longVToken);

    /**
     * @notice Gets the short vToken for this position
     * @return shortVToken Address of the short market vToken
     */
    function shortVToken() external view returns (address shortVToken);
}

contracts/RelativePositionManager/IRelat.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.28;

import { IVToken } from "../Interfaces.sol";

/**
 * @title IRelativePositionManager
 * @author Venus Protocol
 * @notice Interface for the Relative Position Manager contract
 * @dev This contract manages isolated leveraged positions using 3-token logic (DSA + Long + Short)
 *      where positions are opened on behalf of PositionAccount contracts deployed per user per position pair.
 */
interface IRelativePositionManager {
    /// @notice Structure representing a user's position
    struct Position {
        address user; // User who owns this position (immutable)
        address longVToken; // Long vToken market (immutable)
        address shortVToken; // Short vToken market (immutable)
        address positionAccount; // Address of the PositionAccount contract (immutable)
        bool isActive; // Whether position is currently active (mutable)
        uint8 dsaIndex; // Index of DSA in dsaVTokens array sets on activation (mutable)
        address dsaVToken; // DSA vToken market address sets on activation (mutable)
        uint256 suppliedPrincipalVTokens; // Total DSA supplied as collateral, in vToken amount (mutable)
        uint256 effectiveLeverage; // Leverage ratio sets on activation (mutable)
        uint256 cycleId; // Current cycle ID, increments on each activation (mutable)
    }

    /// @notice Structure for utilization calculation results
    struct UtilizationInfo {
        uint256 actualCapitalUtilized; // Capital used based on collateral LTV ratios (in USD)
        uint256 nominalCapitalUtilized; // Capital used based on leverage ratio (in USD)
        uint256 finalCapitalUtilized; // Position capital capped by supplied principal (in USD)
        uint256 availableCapitalUSD; // Remaining capital available for borrowing (in USD)
        uint256 withdrawableAmount; // Amount that can be withdrawn in DSA token terms
    }

    /// @dev USD values for long collateral, short debt, and supplied principal (and prices used for conversions)
    struct PositionValuesUSD {
        uint256 longValueUSD;
        uint256 borrowValueUSD;
        uint256 suppliedPrincipalUSD;
        uint256 dsaPrice;
        uint256 shortPrice;
    }

    /// @custom:error PositionAlreadyExists when user tries to activate an already active position
    error PositionAlreadyExists();

    /// @custom:error PositionNotActive when trying to operate on inactive position
    error PositionNotActive();

    /// @custom:error PositionNotFullyClosed when trying to deactivate a position that still has collateral or debt
    error PositionNotFullyClosed();

    /// @custom:error InvalidDSA when DSA index or address is not valid
    error InvalidDSA();

    /// @custom:error DSAInactive when a DSA vToken is configured but not active for new activations
    error DSAInactive();

    /// @custom:error SameDSAActiveStatus when setDSAVTokenActive is called with the current active flag
    error SameDSAActiveStatus();

    /// @custom:error DSAVTokenAlreadyAdded when trying to add an already configured DSA vToken
    error DSAVTokenAlreadyAdded();

    /// @custom:error InsufficientPrincipal when supplied principal is insufficient
    error InsufficientPrincipal();

    /// @custom:error InvalidLeverage when leverage is invalid (0 or too low or exceeds max)
    error InvalidLeverage();

    /// @custom:error BorrowAmountExceedsMaximum when borrow amount exceeds the calculated maximum based on capital utilization
    error BorrowAmountExceedsMaximum();

    /// @custom:error InsufficientWithdrawableAmount when trying to withdraw more than allowed
    error InsufficientWithdrawableAmount();

    /// @custom:error ZeroAddress when a zero address is provided
    error ZeroAddress();

    /// @custom:error InvalidOraclePrice when oracle returns zero or invalid price
    error InvalidOraclePrice();

    /// @custom:error AssetNotListed when asset market is not listed in comptroller
    error AssetNotListed();

    /// @custom:error VBNBNotSupported when trying to use vBNB market
    error VBNBNotSupported();

    /// @custom:error MintBehalfFailed when minting vTokens on behalf fails
    /// @param errorCode Error code returned by the vToken mintBehalf call
    error MintBehalfFailed(uint256 errorCode);

    /// @custom:error EnterMarketFailed when entering market on behalf fails
    error EnterMarketFailed(uint256 errorCode);

    /// @custom:error ZeroAmount when amount is zero
    error ZeroAmount();

    /// @custom:error ZeroShortAmount when borrow amount is zero
    error ZeroShortAmount();

    /// @custom:error ZeroDebt when there is no short debt to close
    error ZeroDebt();

    /// @custom:error SameMarketNotAllowed when long and short markets are identical
    error SameMarketNotAllowed();

    /// @custom:error MinAmountOutSecondBelowDebt when minAmountOutSecond is less than remaining short debt (second swap)
    error MinAmountOutSecondBelowDebt();

    /// @custom:error MinAmountOutRepayBelowDebt when minAmountOutRepay is less than current short debt
    error MinAmountOutRepayBelowDebt();

    /// @custom:error RedeemBehalfFailed when redeeming vTokens on behalf fails
    /// @param errorCode Error code returned by the vToken redeemUnderlyingBehalf call
    error RedeemBehalfFailed(uint256 errorCode);

    /// @custom:error TokenSwapCallFailed when swap execution via SwapHelper fails
    error TokenSwapCallFailed();

    /// @custom:error SlippageExceeded when swap output is below the minimum required
    error SlippageExceeded();

    /// @custom:error PositionAccountImplementationNotSet when trying to deploy or compute position accounts before implementation is configured
    error PositionAccountImplementationNotSet();

    /// @custom:error SamePositionAccountImplementation when setter is called with the current implementation address
    error SamePositionAccountImplementation();

    /// @custom:error ProportionalCloseAmountOutOfTolerance when user-provided close amounts are not within 1% of BPS-derived expected amounts
    error ProportionalCloseAmountOutOfTolerance();

    /// @custom:error InvalidCollateralFactor when a market's collateral factor is configured to be >= 100%
    error InvalidCollateralFactor();

    /// @custom:error InvalidLongAmountToRedeem when proportional close expects zero long (no long to close) but user passed non-zero total long amount
    error InvalidLongAmountToRedeem();

    /// @custom:error InvalidCloseFractionBps when closeFractionBps is not between 1 and 100 (percentage)
    error InvalidCloseFractionBps();

    /// @notice Emitted when a user activates a position account
    /// @param user Address of the user
    /// @param longAsset Address of the long asset
    /// @param shortAsset Address of the short asset
    /// @param dsaAsset Address of the DSA asset
    /// @param positionAccount Address of the deployed PositionAccount
    /// @param initialPrincipal Initial principal supplied (optional)
    /// @param effectiveLeverage Target leverage ratio for the position
    event PositionActivated(
        address indexed user,
        address indexed longAsset,
        address indexed shortAsset,
        address dsaAsset,
        address positionAccount,
        uint256 cycleId,
        uint256 initialPrincipal,
        uint256 effectiveLeverage
    );

    /// @notice Emitted when a user supplies additional principal
    /// @param user Address of the user
    /// @param positionAccount Address of the position account
    /// @param cycleId The cycle ID of the position
    /// @param dsaAsset Address of the DSA asset
    /// @param amount Amount supplied
    /// @param newTotalPrincipal New total principal amount
    event PrincipalSupplied(
        address indexed user,
        address indexed positionAccount,
        uint256 cycleId,
        address dsaAsset,
        uint256 amount,
        uint256 newTotalPrincipal
    );

    /// @notice Emitted when a position is opened or scaled (borrow + swap to long)
    /// @param user Address of the user
    /// @param positionAccount Address of the position account
    /// @param longAsset Address of the long asset
    /// @param shortAsset Address of the short asset
    /// @param dsaAsset Address of the DSA asset
    /// @param shortAmount Amount borrowed in short asset
    /// @param additionalPrincipal Additional principal supplied this call (0 if none)
    event PositionOpened(
        address indexed user,
        address indexed positionAccount,
        uint256 cycleId,
        address longAsset,
        address shortAsset,
        address dsaAsset,
        uint256 shortAmount,
        uint256 additionalPrincipal
    );

    /// @notice Emitted when a position is closed (partially or fully)
    /// @param user Address of the user
    /// @param positionAccount Address of the position account
    /// @param cycleId The cycle ID of the position
    /// @param closeFractionBps Proportion closed in percentage (100 = 100%)
    /// @param amountRepaid Short debt repaid in this close
    /// @param amountRedeemed Long collateral redeemed in this close
    /// @param amountRedeemedDsa DSA amount redeemed in this close (loss close second leg; 0 for profit close)
    /// @param longDustRedeemed Remaining long collateral redeemed and transferred to user on 100% close (0 for partial close)
    event PositionClosed(
        address indexed user,
        address indexed positionAccount,
        uint256 cycleId,
        uint256 closeFractionBps,
        uint256 amountRepaid,
        uint256 amountRedeemed,
        uint256 amountRedeemedDsa,
        uint256 longDustRedeemed
    );

    /// @notice Emitted when long is converted to profit (DSA) during closeWithProfit
    /// @param user Address of the user
    /// @param positionAccount Address of the position account
    /// @param amountConvertedToProfit Long amount redeemed and swapped to DSA as profit (underlying terms)
    /// @param newTotalPrincipal New total principal amount in vTokens after conversion
    event ProfitConverted(
        address indexed user,
        address indexed positionAccount,
        uint256 amountConvertedToProfit,
        uint256 newTotalPrincipal
    );

    /// @notice Emitted when principal is withdrawn
    /// @param user Address of the user
    /// @param positionAccount Address of the position account
    /// @param dsaAsset Address of the DSA asset
    /// @param amount Amount withdrawn
    /// @param remainingPrincipal Remaining principal after withdrawal
    event PrincipalWithdrawn(
        address indexed user,
        address indexed positionAccount,
        address dsaAsset,
        uint256 amount,
        uint256 remainingPrincipal
    );

    /// @notice Emitted when a position is deactivated
    /// @param user Address of the user
    /// @param positionAccount Address of the position account
    /// @param cycleId The cycle ID of the position
    /// @param dsaAsset Address of the DSA asset used for principal
    /// @param amountWithdrawn Amount of DSA underlying withdrawn on deactivation
    event PositionDeactivated(
        address indexed user,
        address indexed positionAccount,
        uint256 cycleId,
        address dsaAsset,
        uint256 amountWithdrawn
    );

    /// @notice Emitted when underlying tokens are transferred from this contract to a user
    /// @param token Address of the underlying ERC20 token
    /// @param from Account on whose behalf the underlying was redeemed
    /// @param to Recipient address (typically msg.sender)
    /// @param amount Amount of underlying transferred
    event UnderlyingTransferred(address indexed token, address indexed from, address indexed to, uint256 amount);

    /// @notice Emitted when supplied principal is refreshed down to match actual vToken balance (e.g. after liquidation seized vTokens)
    /// @param user Position owner
    /// @param positionAccount Position account whose principal was refreshed
    /// @param oldSuppliedPrincipal Previous suppliedPrincipal (vToken amount)
    /// @param newSuppliedPrincipal New suppliedPrincipal (capped at actual vToken balance)
    event RefreshedSuppliedPrincipal(
        address indexed user,
        address indexed positionAccount,
        uint256 oldSuppliedPrincipal,
        uint256 newSuppliedPrincipal
    );

    /// @notice Emitted when a new DSA vToken is added
    /// @param dsaVToken Address of the DSA vToken added
    /// @param index Index of the DSA vToken in the array
    event DSAVTokenAdded(address indexed dsaVToken, uint8 index);

    /// @notice Emitted when the active flag for a DSA vToken is updated
    /// @param dsaVToken Address of the DSA vToken
    /// @param index Index of the DSA vToken in the internal mapping
    /// @param active New active flag (true to allow new activations, false to block them)
    event DSAVTokenActiveUpdated(address indexed dsaVToken, uint8 index, bool active);

    /// @notice Emitted when the PositionAccount implementation address is updated
    /// @param oldImplementation Previous implementation address (zero if first set)
    /// @param newImplementation New implementation address
    event PositionAccountImplementationUpdated(address indexed oldImplementation, address indexed newImplementation);

    /// @notice Emitted when a new PositionAccount clone is deployed for a user and asset pair
    /// @param user Owner of the position account
    /// @param longAsset Long asset vToken address
    /// @param shortAsset Short asset vToken address
    /// @param positionAccount Address of the deployed PositionAccount clone
    event PositionAccountDeployed(
        address indexed user,
        address indexed longAsset,
        address indexed shortAsset,
        address positionAccount
    );

    /**
     * @notice Returns the number of configured DSA vTokens (also the next index to assign)
     * @return count Current value of the DSA vToken index counter
     */
    function dsaVTokenIndexCounter() external view returns (uint8 count);

    /**
     * @notice Activates a position account for the user with specified asset pair and DSA
     * @dev Deploys a new PositionAccount contract if one doesn't exist for this user/asset combination.
     *      The effective leverage must be set during activation and will be used to validate borrow amounts
     *      in openPosition operations.
     * @param longVToken The vToken market address for the asset to long
     * @param shortVToken The vToken market address for the asset to short
     * @param dsaIndex Index of the DSA vToken in the dsaVTokens array
     * @param initialPrincipal Optional initial principal amount to supply
     * @param effectiveLeverage The target leverage ratio for this position (in mantissa, e.g., 2e18 = 2x leverage)
     */
    function activatePosition(
        address longVToken,
        address shortVToken,
        uint8 dsaIndex,
        uint256 initialPrincipal,
        uint256 effectiveLeverage
    ) external;

    /**
     * @notice Activates and opens a position in a single transaction
     * @dev Runs activatePosition flow first, then openPosition flow.
     * @param longVToken The vToken market address for the asset to long
     * @param shortVToken The vToken market address for the asset to short
     * @param dsaIndex Index of the DSA vToken in the dsaVTokens array
     * @param initialPrincipal Optional initial principal amount to supply during activation
     * @param effectiveLeverage The target leverage ratio for this position
     * @param shortAmount Amount to borrow in shortAsset terms
     * @param minLongAmount Minimum amount of long asset expected from swap
     * @param swapData Swap instructions for converting shortAsset to longAsset
     */
    function activateAndOpenPosition(
        address longVToken,
        address shortVToken,
        uint8 dsaIndex,
        uint256 initialPrincipal,
        uint256 effectiveLeverage,
        uint256 shortAmount,
        uint256 minLongAmount,
        bytes calldata swapData
    ) external;

    /**
     * @notice Supplies additional principal to an active position
     * @dev Can be called multiple times to increase collateral. DSA is taken from the position (set on activation).
     * @param longVToken The vToken market address for the long asset
     * @param shortVToken The vToken market address for the short asset
     * @param amount Amount of DSA underlying to supply
     */
    function supplyPrincipal(address longVToken, address shortVToken, uint256 amount) external;

    /**
     * @notice Opens a leveraged position or scales an existing one (borrow short, swap to long)
     * @dev Can be called multiple times to scale the position. Optionally supply additional principal
     *      via additionalPrincipal; otherwise uses existing principal. Validates that shortAmount doesn't
     *      exceed the maximum allowed based on capital utilization. DSA is taken from the position (set during activation).
     * @param longVToken The vToken market for the asset to long
     * @param shortVToken The vToken market for the asset to short
     * @param additionalPrincipal Additional principal to supply this call (0 if none)
     * @param shortAmount Amount to borrow in shortAsset terms (must not exceed max calculated borrow)
     * @param minLongAmount Minimum amount of long asset expected from swap (protects against slippage)
     * @param swapData Swap instructions for converting shortAsset to longAsset
     */
    function openPosition(
        IVToken longVToken,
        IVToken shortVToken,
        uint256 additionalPrincipal,
        uint256 shortAmount,
        uint256 minLongAmount,
        bytes calldata swapData
    ) external;

    /**
     * @notice Closes a position proportionally; can realize profit on the closed slice (partial or full)
     * @dev Repay amount is derived from BPS. Total long validated against BPS (within PROPORTIONAL_CLOSE_TOLERANCE). minAmountOutRepay must be >= calculated repay.
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @param closeFractionBps Proportion to close in percentage (100 = 100%, 1 = 1% minimum)
     * @param longAmountToRedeemForRepay Amount of long to redeem for the repay leg (validated against BPS)
     * @param minAmountOutRepay Minimum short out from the repay swap (must be >= calculated repay amount for this BPS)
     * @param swapDataRepay Swap #1: long → short for debt repayment
     * @param longAmountToRedeemForProfit Amount of long to redeem and swap long→DSA as profit (can be non-zero for partial or full close)
     * @param minAmountOutProfit Minimum DSA out from the profit swap
     * @param swapDataProfit Swap #2: long → DSA for profit realization
     */
    function closeWithProfit(
        IVToken longVToken,
        IVToken shortVToken,
        uint256 closeFractionBps,
        uint256 longAmountToRedeemForRepay,
        uint256 minAmountOutRepay,
        bytes calldata swapDataRepay,
        uint256 longAmountToRedeemForProfit,
        uint256 minAmountOutProfit,
        bytes calldata swapDataProfit
    ) external;

    /**
     * @notice Closes a position with loss proportionally
     * @dev closeFractionBps: 100 = 100%, 1 = 1% min. First-exit long is proportion-derived; short repay in [0, expectedShort].
     *      First exit long→short, second exit DSA→short for remainder. Position fully closed.
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @param closeFractionBps Proportion to close in percentage (100 = 100%)
     * @param longAmountToRedeemForFirstSwap Long to redeem for first swap (validated against BPS within PROPORTIONAL_CLOSE_TOLERANCE)
     * @param shortAmountToRepayForFirstSwap Short to repay in first exit (0 <= value <= BPS-derived expected short)
     * @param minAmountOutFirst Minimum amount out from first swap (must be >= borrowedAmountToRepayFirst when first repay > 0)
     * @param swapDataFirst Calldata for first swap (long → short)
     * @param dsaAmountToRedeemForSecondSwap DSA to redeem for second exit repay
     * @param minAmountOutSecond Minimum amount out from second swap
     * @param swapDataSecond Calldata for second swap (DSA → short)
     */
    function closeWithLoss(
        IVToken longVToken,
        IVToken shortVToken,
        uint256 closeFractionBps,
        uint256 longAmountToRedeemForFirstSwap,
        uint256 shortAmountToRepayForFirstSwap,
        uint256 minAmountOutFirst,
        bytes calldata swapDataFirst,
        uint256 dsaAmountToRedeemForSecondSwap,
        uint256 minAmountOutSecond,
        bytes calldata swapDataSecond
    ) external;

    /**
     * @notice Withdraws unused principal from an active position
     * @dev Calculates utilization to determine how much can be safely withdrawn.
     *      The DSA asset is retrieved from the position data (set during activation).
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @param amount Amount to withdraw
     */
    function withdrawPrincipal(IVToken longVToken, IVToken shortVToken, uint256 amount) external;

    /**
     * @notice Deactivates a position account
     * @dev Removes DSA selection and resets leverage. User can activate with new DSA later.
     *      The DSA asset is retrieved from the position data (set during activation).
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     */
    function deactivatePosition(IVToken longVToken, IVToken shortVToken) external;

    /**
     * @notice Adds a new DSA vToken to the supported list
     * @dev Index will be the current length of the array. Callable only by accounts with ACM permission for addDSAVToken(address).
     * @param dsaVToken The vToken market address to add as a supported DSA
     */
    function addDSAVToken(address dsaVToken) external;

    /**
     * @notice Returns the full list of configured DSA vToken markets
     * @dev Convenience helper for frontends; underlying storage is the public dsaVTokens array.
     * @return dsaVTokensList Array of DSA vToken addresses
     */
    function getDsaVTokens() external view returns (address[] memory dsaVTokensList);

    /**
     * @notice Updates the active flag for a configured DSA vToken, controlling whether it can be used for new activations
     * @dev Callable only by accounts with ACM permission for setDSAVTokenActive(uint8,bool).
     *      Does not affect already active positions, which may continue to close or withdraw principal.
     * @param dsaIndex Index of the DSA vToken in the internal mapping
     * @param active New active flag (true to allow new activations, false to block them)
     */
    function setDSAVTokenActive(uint8 dsaIndex, bool active) external;

    /**
     * @notice Returns the address at which the PositionAccount would be deployed for the given user and markets
     * @dev Same salt as used when deploying via activatePosition. Returns the address that would be used if the position account were deployed.
     * @param user User address
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @return predicted The predicted PositionAccount address
     */
    function getPositionAccountAddress(
        address user,
        IVToken longVToken,
        IVToken shortVToken
    ) external view returns (address predicted);

    /**
     * @notice Updates the implementation contract used for PositionAccount clones
     * @dev Callable only by accounts with ACM permission for setPositionAccountImplementation(address).
     *      Must be configured before any position accounts can be deployed or predicted.
     * @param positionAccountImpl Implementation contract for PositionAccount EIP-1167 clones
     */
    function setPositionAccountImplementation(address positionAccountImpl) external;

    /**
     * @notice Returns the position data for a user and asset pair
     * @param user User address
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @return position The Position struct (user, longVToken, shortVToken, positionAccount, isActive, dsaIndex, dsaVToken, suppliedPrincipalVTokens, effectiveLeverage, cycleId)
     */
    function getPosition(
        address user,
        IVToken longVToken,
        IVToken shortVToken
    ) external view returns (Position memory position);

    /**
     * @notice Returns the actual long collateral balance in underlying for a given user/position,
     *         excluding DSA principal when the DSA and long assets share the same vToken market.
     * @param user The position owner
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @return longBalance The long collateral balance in underlying units (principal excluded when shared market)
     */
    function getLongCollateralBalance(
        address user,
        IVToken longVToken,
        IVToken shortVToken
    ) external returns (uint256 longBalance);

    /**
     * @notice Returns the supplied principal balance in underlying units for a given user/position
     * @param user The position owner
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @return balance The supplied principal in underlying units
     */
    function getSuppliedPrincipalBalance(
        address user,
        IVToken longVToken,
        IVToken shortVToken
    ) external returns (uint256 balance);

    /**
     * @notice Executes multiple generic calls on behalf of a position account
     * @dev Callable by governance, Allows operations like emergency fund rescues.
     * @param positionAccount Address of the position account
     * @param targets Array of target contract addresses
     * @param data Array of encoded function call data
     */
    function executePositionAccountCall(
        address positionAccount,
        address[] calldata targets,
        bytes[] calldata data
    ) external;

    /**
     * @notice Pauses state-changing user operations on the manager (activation, open/close, principal changes).
     * @dev Callable only by governance via AccessControlManager.
     */
    function pause() external;

    /**
     * @notice Unpauses state-changing user operations on the manager.
     * @dev Callable only by governance via AccessControlManager.
     */
    function unpause() external;

    /**
     * @notice Calculates capital utilization for a position
     * @dev Computes how much capital is being used vs available:
     *      1. Calculates actual capital utilized (based on collateral LTV ratios)
     *      2. Calculates nominal capital utilized (based on leverage ratio)
     *      3. Takes max (more conservative estimate)
     *      4. Caps by supplied principal
     *      5. Calculates available capital remaining
     *      6. Calculates withdrawable amount in DSA token terms
     *      Used by calculateMaxBorrow to determine maximum borrowing capacity. DSA is read from the position.
     * @param user User address
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @return utilization Utilization information including available capital and withdrawable amount
     */
    function getUtilizationInfo(
        address user,
        IVToken longVToken,
        IVToken shortVToken
    ) external returns (UtilizationInfo memory utilization);

    /**
     * @notice Calculates the maximum allowed borrow amount for a position
     * @dev Uses getUtilizationInfo internally to get available capital, then calculates:
     *      maxBorrow = availableCapital * effectiveLeverage
     *      This leverages the sophisticated capital utilization calculation in getUtilizationInfo. DSA is read from the position.
     * @param user User address
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @return maxBorrowAmount Maximum amount that can be borrowed in shortAsset terms
     */
    function calculateMaxBorrow(
        address user,
        IVToken longVToken,
        IVToken shortVToken
    ) external returns (uint256 maxBorrowAmount);
}

contracts/RelativePositionManager/Relati.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.28;

import { ReentrancyGuardUpgradeable } from "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import { PausableUpgradeable } from "@openzeppelin/contracts-upgradeable/security/PausableUpgradeable.sol";
import {
    SafeERC20Upgradeable,
    IERC20Upgradeable
} from "@openzeppelin/contracts-upgradeable/token/ERC20/utils/SafeERC20Upgradeable.sol";
import { ClonesUpgradeable } from "@openzeppelin/contracts-upgradeable/proxy/ClonesUpgradeable.sol";
import { AccessControlledV8 } from "@venusprotocol/governance-contracts/contracts/Governance/AccessControlledV8.sol";
import { IVToken, IComptroller } from "../Interfaces.sol";
import { ResilientOracleInterface } from "@venusprotocol/oracle/contracts/interfaces/OracleInterface.sol";
import { LeverageStrategiesManager } from "../LeverageManager/LeverageStrategiesManager.sol";
import { IRelativePositionManager } from "./IRelativePositionManager.sol";
import { IPositionAccount } from "./IPositionAccount.sol";

/**
 * @title RelativePositionManager
 * @author Venus Protocol
 * @notice Contract for managing isolated leveraged positions with relative price trading interface
 * @dev This contract provides a simplified interface for users to open positions that feel like
 *      trading relative prices rather than traditional leverage. Uses 3-token logic (DSA + Long + Short)
 *      and deploys isolated PositionAccount contracts for each position.
 */
contract RelativePositionManager is
    AccessControlledV8,
    ReentrancyGuardUpgradeable,
    PausableUpgradeable,
    IRelativePositionManager
{
    using SafeERC20Upgradeable for IERC20Upgradeable;

    /// @dev Success return value for Comptroller operations (e.g. enterMarketBehalf)
    uint256 private constant SUCCESS = 0;

    /// @dev Mantissa for fixed-point arithmetic (MANTISSA_ONE = 100%)
    uint256 private constant MANTISSA_ONE = 1e18;

    /// @dev Minimum leverage ratio (1x)
    uint256 private constant MIN_LEVERAGE = MANTISSA_ONE;

    /// @dev Proportional close in percentage: 100 = 100%, 1 = 1% minimum
    uint256 private constant PROPORTIONAL_CLOSE_MIN = 1;
    uint256 private constant PROPORTIONAL_CLOSE_MAX = 100;

    /// @dev Tolerance for proportional close: 100 = 1% margin of error // TBD (also can make a setter for this)
    uint256 private constant PROPORTIONAL_CLOSE_TOLERANCE = 2;

    /// @notice The Venus comptroller contract
    IComptroller public immutable COMPTROLLER;

    /// @notice The leverage strategies manager contract
    LeverageStrategiesManager public immutable LEVERAGE_MANAGER;

    /// @notice Implementation contract for PositionAccount clones (settable via governance)
    address public POSITION_ACCOUNT_IMPLEMENTATION;

    /// @notice Counter / next index for newly added DSA vTokens (also equals current count)
    uint8 public dsaVTokenIndexCounter;

    /// @notice Mapping from DSA index to supported DSA (Default Settlement Asset) vToken markets
    mapping(uint8 => address) public dsaVTokens;

    /// @notice Tracks whether a given DSA vToken is currently active for new activations
    mapping(address => bool) public isDsaVTokenActive;

    /// @notice Mapping from user => longAsset => shortAsset => Position data
    mapping(address => mapping(address => mapping(address => Position))) public positions;

    /**
     * @dev This empty reserved space is put in place to allow future versions to add new
     * variables without shifting down storage in the inheritance chain.
     * See https://docs.openzeppelin.com/contracts/4.x/upgradeable#storage_gaps
     */
    uint256[45] private __gap;

    /**
     * @notice Contract constructor
     * @param comptroller The Venus Comptroller contract address
     * @param leverageManager The LeverageStrategiesManager contract address (provides swap helper for enter/exit leverage)
     * @custom:oz-upgrades-unsafe-allow constructor
     */
    constructor(address comptroller, address leverageManager) {
        if (comptroller == address(0) || leverageManager == address(0)) {
            revert ZeroAddress();
        }

        COMPTROLLER = IComptroller(comptroller);
        LEVERAGE_MANAGER = LeverageStrategiesManager(leverageManager);

        _disableInitializers();
    }

    /**
     * @notice Initializes the upgradeable contract
     * @param accessControlManager_ Address of the Access Control Manager contract
     */
    function initialize(address accessControlManager_) external initializer {
        __AccessControlled_init(accessControlManager_);
        __ReentrancyGuard_init();
        __Pausable_init();
    }

    /**
     * @notice Pauses state-changing user operations on the manager (activation, opening/closing, principal changes)
     * @dev Callable only by governance via AccessControlManager. View and admin functions remain available.
     */
    function pause() external {
        _checkAccessAllowed("pause()");
        _pause();
    }

    /**
     * @notice Unpauses state-changing user operations on the manager
     * @dev Callable only by governance via AccessControlManager.
     */
    function unpause() external {
        _checkAccessAllowed("unpause()");
        _unpause();
    }

    /**
     * @notice Updates the implementation contract used for PositionAccount clones
     * @dev Callable only by governance via AccessControlManager. Must be set before any positions are activated.
     * @param positionAccountImpl Implementation contract for PositionAccount EIP-1167 clones
     * @custom:error Throw ZeroAddress if positionAccountImpl is zero.
     * @custom:error Throw SamePositionAccountImplementation if the implementation is unchanged.
     * @custom:event Emits PositionAccountImplementationUpdated event.
     */
    function setPositionAccountImplementation(address positionAccountImpl) external {
        _checkAccessAllowed("setPositionAccountImplementation(address)");

        if (positionAccountImpl == address(0)) {
            revert ZeroAddress();
        }

        address oldImpl = POSITION_ACCOUNT_IMPLEMENTATION;
        if (oldImpl == positionAccountImpl) {
            revert SamePositionAccountImplementation();
        }

        POSITION_ACCOUNT_IMPLEMENTATION = positionAccountImpl;
        emit PositionAccountImplementationUpdated(oldImpl, positionAccountImpl);
    }

    /**
     * @notice Adds a new DSA vToken to the supported list
     * @dev Index will be the current length of the array. Callable only by Governance.
     * @param dsaVToken The vToken market address to add as a supported DSA
     * @custom:error Throw ZeroAddress if dsaVToken is zero.
     * @custom:error Throw AssetNotListed if the market is not listed in the Comptroller.
     * @custom:error Throw DSAVTokenAlreadyAdded if the DSA vToken is already configured.
     * @custom:event Emits DSAVTokenAdded event.
     */
    function addDSAVToken(address dsaVToken) external {
        // _checkAccessAllowed("addDSAVToken(address)");
        _checkMarketListed(dsaVToken);

        // Revert if this DSA vToken is already configured
        uint8 currentCount = dsaVTokenIndexCounter;
        for (uint8 i = 0; i < currentCount; ++i) {
            if (dsaVTokens[i] == dsaVToken) {
                revert DSAVTokenAlreadyAdded();
            }
        }

        dsaVTokens[currentCount] = dsaVToken;
        isDsaVTokenActive[dsaVToken] = true;
        dsaVTokenIndexCounter = currentCount + 1;

        emit DSAVTokenAdded(dsaVToken, currentCount);
    }

    /**
     * @notice Updates the active flag for a configured DSA vToken, controlling whether it can be used for new activations
     * @dev Callable only by governance via AccessControlManager. Does not affect already active positions,
     *      which may continue to close or withdraw principal using the previously selected DSA.
     * @param dsaIndex Index of the DSA vToken in the internal mapping
     * @param active New active flag (true to allow new activations, false to block them)
     * @custom:error Throw InvalidDSA if the index or stored address is invalid.
     * @custom:error Throw SameDSAActiveStatus when called with the current active flag.
     * @custom:event Emits DSAVTokenActiveUpdated when the active flag is changed.
     */
    function setDSAVTokenActive(uint8 dsaIndex, bool active) external {
        // _checkAccessAllowed("setDSAVTokenActive(uint8,bool)");
        if (dsaIndex >= dsaVTokenIndexCounter) revert InvalidDSA();
        address dsaVToken = dsaVTokens[dsaIndex];
        if (dsaVToken == address(0)) revert InvalidDSA();
        if (isDsaVTokenActive[dsaVToken] == active) revert SameDSAActiveStatus();
        isDsaVTokenActive[dsaVToken] = active;
        emit DSAVTokenActiveUpdated(dsaVToken, dsaIndex, active);
    }

    /**
     * @notice Executes multiple generic calls on behalf of a position account
     * @dev Callable by governance via AccessControlManager. Intended for emergency or administrative actions.
     * @param positionAccount Address of the position account
     * @param targets Array of target contract addresses
     * @param data Array of encoded function call data
     */
    function executePositionAccountCall(
        address positionAccount,
        address[] calldata targets,
        bytes[] calldata data
    ) external nonReentrant {
        // _checkAccessAllowed("executePositionAccountCall(address,address[],bytes[])");
        IPositionAccount(positionAccount).genericCalls(targets, data);
    }

    /**
     * @notice Activates and opens a position in a single transaction
     * @dev Runs activatePosition flow first, then openPosition flow.
     * @param longVToken The vToken market address for the asset to long
     * @param shortVToken The vToken market address for the asset to short
     * @param dsaIndex Index of the DSA vToken in the dsaVTokens array
     * @param initialPrincipal initial principal amount to supply during activation
     * @param effectiveLeverage The target leverage ratio for this position
     * @param shortAmount Amount to borrow in shortAsset terms
     * @param minLongAmount Minimum amount of long asset expected from swap
     * @param swapData Swap instructions for converting shortAsset to longAsset
     */
    function activateAndOpenPosition(
        address longVToken,
        address shortVToken,
        uint8 dsaIndex,
        uint256 initialPrincipal,
        uint256 effectiveLeverage,
        uint256 shortAmount,
        uint256 minLongAmount,
        bytes calldata swapData
    ) external whenNotPaused {
        activatePosition(longVToken, shortVToken, dsaIndex, initialPrincipal, effectiveLeverage);
        openPosition(IVToken(longVToken), IVToken(shortVToken), 0, shortAmount, minLongAmount, swapData);
    }

    /**
     * @notice Supplies additional principal to an active position
     * @dev Can be called multiple times to increase collateral. DSA is taken from the position (set on activation).
     * @param longVToken The vToken market address for the long asset
     * @param shortVToken The vToken market address for the short asset
     * @param amount Amount of DSA underlying to supply
     * @custom:error Throw ZeroAmount if amount is zero.
     * @custom:error Throw PositionNotActive if the position is not active.
     * @custom:event Emits PrincipalSupplied event.
     */
    function supplyPrincipal(
        address longVToken,
        address shortVToken,
        uint256 amount
    ) external nonReentrant whenNotPaused {
        if (amount == 0) revert ZeroAmount();
        Position storage position = _getActivePosition(msg.sender, longVToken, shortVToken);
        _supplyPrincipalToPositionAccount(position, IVToken(position.dsaVToken), amount);
    }

    /**
     * @notice Activates a position account for the user with specified asset pair and DSA
     * @dev Deploys a new PositionAccount contract if one doesn't exist for this user/asset combination.
     *      The effective leverage must be set during activation and will be used to validate borrow amounts
     *      in openPosition operations.
     * @param longVToken The vToken market address for the asset to long
     * @param shortVToken The vToken market address for the asset to short
     * @param dsaIndex Index of the DSA vToken in the dsaVTokens array
     * @param initialPrincipal Optional initial principal amount to supply
     * @param effectiveLeverage The target leverage ratio for this position (in mantissa, e.g., 2e18 = 2x leverage)
     * @custom:error Throw ZeroAddress if longVToken or shortVToken is zero.
     * @custom:error Throw SameMarketNotAllowed if long and short vTokens are identical.
     * @custom:error Throw AssetNotListed if a market is not listed.
     * @custom:error Throw InvalidDSA if dsaIndex is invalid or market not listed.
     * @custom:error Throw DSAInactive if the chosen DSA vToken is configured but not active for new activations.
     * @custom:error Throw InvalidLeverage if effectiveLeverage is out of range.
     * @custom:error Throw PositionAlreadyExists if the position is already active.
     * @custom:error Throw EnterMarketFailed if entering the DSA market on behalf fails.
     * @custom:error Throw MintBehalfFailed if minting initial principal fails.
     * @custom:event Emits PositionActivated or PositionAccountDeployed (if new account) and possibly PrincipalSupplied.
     */
    function activatePosition(
        address longVToken,
        address shortVToken,
        uint8 dsaIndex,
        uint256 initialPrincipal,
        uint256 effectiveLeverage
    ) public nonReentrant whenNotPaused {
        _checkMarketListed(longVToken);
        _checkMarketListed(shortVToken);
        IVToken dsaVToken = _getValidatedDSAVToken(dsaIndex);
        _checkSameMarket(longVToken, shortVToken);

        // Validate requested leverage against [MIN_LEVERAGE, maxLeverage]; λ_max = CF_c / (1 - CF_l * (1 - f))
        uint256 maxLeverage = _getMaxLeverage(dsaVToken, longVToken);
        if (effectiveLeverage < MIN_LEVERAGE || effectiveLeverage > maxLeverage) {
            revert InvalidLeverage();
        }

        Position storage position = positions[msg.sender][longVToken][shortVToken];
        if (position.isActive) {
            revert PositionAlreadyExists();
        }

        // Deploy position account if it doesn't exist (sets immutable fields in _deployPositionAccount)
        if (position.positionAccount == address(0)) {
            _deployPositionAccount(msg.sender, longVToken, shortVToken);
        }

        // Increment cycle ID on each activation and set mutable fields
        position.cycleId++;
        position.isActive = true;
        position.dsaIndex = dsaIndex;
        position.dsaVToken = address(dsaVToken);
        position.effectiveLeverage = effectiveLeverage;

        // Enter DSA market on behalf of position account (to use as collateral)
        _validateAndEnterMarket(position.positionAccount, dsaVToken);

        if (initialPrincipal > 0) {
            _supplyPrincipalToPositionAccount(position, dsaVToken, initialPrincipal);
        }

        emit PositionActivated(
            msg.sender,
            longVToken,
            shortVToken,
            address(dsaVToken),
            position.positionAccount,
            position.cycleId,
            initialPrincipal,
            effectiveLeverage
        );
    }

    /**
     * @notice Opens a leveraged position or scales an existing one (borrow short, swap to long)
     * @dev Can be called multiple times to scale the position. Optionally supply additional principal
     *      via additionalPrincipal; otherwise uses existing principal. Requires either existing principal
     *      (from activation or prior supply) or additionalPrincipal > 0. Validates that shortAmount
     *      doesn't exceed the maximum allowed based on capital utilization. DSA is taken from the position (set on activation).
     * @param longVToken The vToken market for the asset to long
     * @param shortVToken The vToken market for the asset to short
     * @param additionalPrincipal Additional principal to supply this call (0 if none)
     * @param shortAmount Amount to borrow in shortAsset terms (must not exceed max calculated borrow)
     * @param minLongAmount Minimum amount of long asset expected from swap (protects against slippage)
     * @param swapData Swap instructions for converting shortAsset to longAsset
     * @custom:error Throw ZeroShortAmount if shortAmount is zero.
     * @custom:error Throw PositionNotActive if the position is not active.
     * @custom:error Throw InsufficientPrincipal if no principal exists and additionalPrincipal is zero.
     * @custom:error Throw BorrowAmountExceedsMaximum if shortAmount exceeds max allowed borrow.
     * @custom:event Emits PositionOpened event (and PrincipalSupplied if additionalPrincipal > 0).
     */
    function openPosition(
        IVToken longVToken,
        IVToken shortVToken,
        uint256 additionalPrincipal,
        uint256 shortAmount,
        uint256 minLongAmount,
        bytes calldata swapData
    ) public nonReentrant whenNotPaused {
        if (shortAmount == 0) revert ZeroShortAmount();
        Position storage position = _getActivePosition(msg.sender, address(longVToken), address(shortVToken));

        // Must have principal (existing or supplied this call) to collateralize the borrow
        if (position.suppliedPrincipalVTokens == 0 && additionalPrincipal == 0) revert InsufficientPrincipal();
        IVToken dsaVToken = IVToken(position.dsaVToken);

        if (additionalPrincipal > 0) {
            _supplyPrincipalToPositionAccount(position, dsaVToken, additionalPrincipal);
        }

        uint256 maxBorrowAmount = _calculateMaxBorrowAllowed(position);
        if (shortAmount > maxBorrowAmount) revert BorrowAmountExceedsMaximum();

        address positionAccount = position.positionAccount;
        IPositionAccount(positionAccount).enterLeverage(
            longVToken,
            0, // DSA is used as Seed
            shortVToken,
            shortAmount,
            minLongAmount,
            swapData
        );

        // Transfer any dust from LM (sent to position account) to user
        _transferDustFromAccountToUser(positionAccount, longVToken.underlying());
        _transferDustFromAccountToUser(positionAccount, shortVToken.underlying());

        emit PositionOpened(
            msg.sender,
            positionAccount,
            position.cycleId,
            address(longVToken),
            address(shortVToken),
            address(dsaVToken),
            shortAmount,
            additionalPrincipal
        );
    }

    /**
     * @notice Closes a position proportionally; can realize profit on the closed slice (partial or full)
     * @dev Repay amount is derived from given BPS (not passed). Total long (repay + profit) is validated
     *      against BPS (within PROPORTIONAL_CLOSE_TOLERANCE). minAmountOutRepay must be >= expected repay for this BPS;
     *      for 100% close, pass slightly more to cover the internal tolerance bump (exact bump not required).
     *      Principal (DSA) collateral is not touched directly by this function; any unused principal remains on the
     *      position account, withdrawn later via `withdrawPrincipal`, or can be fully swept on `deactivatePosition`.
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @param closeFractionBps Proportion to close in percentage (100 = 100%, 1 = 1% minimum)
     * @param longAmountToRedeemForRepay Amount of long to redeem for the repay leg (validated against BPS)
     * @param minAmountOutRepay Minimum short out from the repay swap (must be >= calculated repay amount for this BPS)
     * @param swapDataRepay Swap #1: long → short for debt repayment
     * @param longAmountToRedeemForProfit Amount of long to redeem and swap long→DSA as profit (can be non-zero for partial or full close)
     * @param minAmountOutProfit Minimum DSA out from the profit swap
     * @param swapDataProfit Swap #2: long → DSA for profit realization
     * @custom:error Throw PositionNotActive if the position is not active.
     * @custom:error Throw SameMarketNotAllowed if long and short vTokens are identical.
     * @custom:error Throw InvalidCloseFractionBps if closeFractionBps is not between 1 and 100.
     * @custom:error Throw MinAmountOutRepayBelowDebt if minAmountOutRepay is below the calculated short debt for this close.
     * @custom:error Throw ProportionalCloseAmountOutOfTolerance if total long amounts are not within the tolerated BPS band.
     * @custom:error Throw RedeemBehalfFailed if profit redemption fails.
     * @custom:error Throw TokenSwapCallFailed if the swap helper call fails, or SlippageExceeded if swap output is too low.
     * @custom:event Emits ProfitConverted and PositionClosed events.
     */
    function closeWithProfit(
        IVToken longVToken,
        IVToken shortVToken,
        uint256 closeFractionBps,
        uint256 longAmountToRedeemForRepay,
        uint256 minAmountOutRepay,
        bytes calldata swapDataRepay,
        uint256 longAmountToRedeemForProfit,
        uint256 minAmountOutProfit,
        bytes calldata swapDataProfit
    ) external nonReentrant whenNotPaused {
        Position storage position = _getActivePosition(msg.sender, address(longVToken), address(shortVToken));

        uint256 amountToRepay = _validateProfitClose(
            position,
            closeFractionBps,
            longAmountToRedeemForRepay + longAmountToRedeemForProfit,
            minAmountOutRepay
        );

        address positionAccount = position.positionAccount;

        // Proportional repay via exitLeverage (amountToRepay already includes 100% tolerance bump when applicable)
        if (amountToRepay > 0) {
            IPositionAccount(positionAccount).exitLeverage(
                longVToken,
                longAmountToRedeemForRepay,
                shortVToken,
                amountToRepay,
                minAmountOutRepay,
                swapDataRepay
            );
        }

        // Realize profit: redeem longAmountToRedeemForProfit and swap to DSA (converted to principal)
        if (longAmountToRedeemForProfit > 0) {
            _redeemLongAndSwapToDSA(
                position,
                positionAccount,
                longVToken,
                IVToken(position.dsaVToken),
                longAmountToRedeemForProfit,
                minAmountOutProfit,
                swapDataProfit
            );
        }

        _transferDustFromAccountToUser(positionAccount, longVToken.underlying());
        _transferDustFromAccountToUser(positionAccount, shortVToken.underlying());

        uint256 longDustRedeemed;
        if (closeFractionBps == PROPORTIONAL_CLOSE_MAX) {
            longDustRedeemed = _verifyFullClose(position, longVToken, shortVToken);
        }

        emit PositionClosed(
            msg.sender,
            positionAccount,
            position.cycleId,
            closeFractionBps,
            amountToRepay,
            longAmountToRedeemForRepay + longAmountToRedeemForProfit,
            0,
            longDustRedeemed
        );
    }

    /**
     * @notice Closes a position with loss proportionally (BPS-based, same pattern as closeWithProfit)
     * @dev
     *      - First exit (long → short): long/short amounts are derived from BPS; the user passes shortAmountToRepayForFirstSwap,
     *        which is validated to be within [0, expectedShort] and minAmountOutFirst must be >= shortAmountToRepayForFirstSwap.
     *        For 100% close with one leg, shortAmountToRepayForFirstSwap should be slightly higher to cover the internal tolerance bump.
     *      - Second exit (DSA → short): the second repay amount is calculated as expectedShort - shortAmountToRepayForFirstSwap
     *        (and bumped for 100% close when > 0). minAmountOutSecond must be >= the calculated second repay (slippage protection; should cover the bump but exact match not required).
     *      - Single-leg scenarios: this function also supports cases where only one leg (long or DSA) is available
     *        (e.g. after liquidation), by allowing either the first or second exit to be effectively skipped
     *      - Principal handling: any remaining principal (DSA) that is not consumed in the loss scenario stays on the
     *        position account even after a full close; it can later be moved to the user by calling `withdrawPrincipal`
     *        or by calling `deactivatePosition`, which fully redeems remaining DSA collateral to the user.
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @param closeFractionBps Proportion to close in percentage (100 = 100%, 1 = 1% minimum)
     * @param longAmountToRedeemForFirstSwap Long amount to redeem for the first swap (validated against BPS within 1% tolerance)
     * @param shortAmountToRepayForFirstSwap Short amount to repay in the first exit (validated: 0 <= value <= BPS-derived expected short)
     * @param minAmountOutFirst Minimum short out from the first swap (must be >= shortAmountToRepayForFirstSwap
     * @param swapDataFirst Swap #1 calldata: long/DSA → short for the first repay leg
     * @param dsaAmountToRedeemForSecondSwap DSA amount to redeem and use as input for the second repay swap
     * @param minAmountOutSecond Minimum short out from the second swap (must be >= internally calculated second repay; for 100% close should cover the bumped amount)
     * @param swapDataSecond Swap #2 calldata: DSA → short for the second repay leg
     * @custom:error Throw PositionNotActive if the position is not active.
     * @custom:error Throw SameMarketNotAllowed if long and short vTokens are identical.
     * @custom:error Throw ZeroDebt if there is no short debt to close.
     * @custom:error Throw InvalidCloseFractionBps if closeFractionBps is not between 1 and 100.
     * @custom:error Throw MinAmountOutRepayBelowDebt if minAmountOutFirst is below shortAmountToRepayForFirstSwap.
     * @custom:error Throw ProportionalCloseAmountOutOfTolerance if first-exit amounts are not within the tolerated BPS band.
     * @custom:error Throw MinAmountOutSecondBelowDebt if minAmountOutSecond is below the internally calculated second repay.
     * @custom:error Throw InsufficientWithdrawableAmount if dsaAmountToRedeemForSecondSwap exceeds available DSA principal.
     * @custom:error Throw RedeemBehalfFailed if redeeming long or DSA vTokens on behalf fails.
     * @custom:error Throw TokenSwapCallFailed if a swap helper call fails, or SlippageExceeded if swap output is too low.
     * @custom:event Emits PositionClosed event.
     */
    function closeWithLoss(
        IVToken longVToken,
        IVToken shortVToken,
        uint256 closeFractionBps,
        uint256 longAmountToRedeemForFirstSwap,
        uint256 shortAmountToRepayForFirstSwap,
        uint256 minAmountOutFirst,
        bytes calldata swapDataFirst,
        uint256 dsaAmountToRedeemForSecondSwap,
        uint256 minAmountOutSecond,
        bytes calldata swapDataSecond
    ) external nonReentrant whenNotPaused {
        Position storage position = _getActivePosition(msg.sender, address(longVToken), address(shortVToken));

        address positionAccount = position.positionAccount;
        if (shortVToken.borrowBalanceCurrent(positionAccount) == 0) revert ZeroDebt();

        // When using DSA principal to repay in the second leg, ensure the requested amount does not exceed
        // the available principal balance (and later update principal accounting accordingly).
        IVToken dsaVToken = IVToken(position.dsaVToken);
        if (dsaAmountToRedeemForSecondSwap > 0) {
            uint256 principalUnderlying = _getSuppliedPrincipalBalance(position);
            if (dsaAmountToRedeemForSecondSwap > principalUnderlying) revert InsufficientWithdrawableAmount();
        }

        uint256 amountToRepaySecond = _validateLossClose(
            position,
            closeFractionBps,
            longAmountToRedeemForFirstSwap,
            shortAmountToRepayForFirstSwap,
            minAmountOutFirst,
            minAmountOutSecond
        );

        // 1. First exitLeverage (long → short): repay first leg of short debt from long collateral.
        if (longAmountToRedeemForFirstSwap > 0) {
            IPositionAccount(positionAccount).exitLeverage(
                longVToken,
                longAmountToRedeemForFirstSwap,
                shortVToken,
                shortAmountToRepayForFirstSwap,
                minAmountOutFirst,
                swapDataFirst
            );
        }

        uint256 dsaAmountRedeemed;
        // 2. Second leg: repay remaining short debt with DSA. When DSA == short use exitSingleAssetLeverage (no swap); else exitLeverage.
        if (amountToRepaySecond > 0) {
            dsaAmountRedeemed = dsaAmountToRedeemForSecondSwap;
            uint256 vTokensBefore = dsaVToken.balanceOf(positionAccount);
            if (address(dsaVToken) == address(shortVToken)) {
                IPositionAccount(positionAccount).exitSingleAssetLeverage(dsaVToken, amountToRepaySecond);
            } else {
                IPositionAccount(positionAccount).exitLeverage(
                    dsaVToken,
                    dsaAmountToRedeemForSecondSwap,
                    shortVToken,
                    amountToRepaySecond,
                    minAmountOutSecond,
                    swapDataSecond
                );
            }
            // Reduce suppliedPrincipalVTokens by DSA vTokens burned for this leg, clamped to tracked principal.
            uint256 burned = vTokensBefore - dsaVToken.balanceOf(positionAccount);
            if (burned > position.suppliedPrincipalVTokens) {
                position.suppliedPrincipalVTokens = 0;
            } else {
                position.suppliedPrincipalVTokens -= burned;
            }
            _transferDustFromAccountToUser(positionAccount, dsaVToken.underlying());
        }

        // Transfer any dust from LM (sent to position account) to user
        _transferDustFromAccountToUser(positionAccount, longVToken.underlying());
        _transferDustFromAccountToUser(positionAccount, shortVToken.underlying());

        uint256 longDustRedeemed;
        if (closeFractionBps == PROPORTIONAL_CLOSE_MAX) {
            longDustRedeemed = _verifyFullClose(position, longVToken, shortVToken);
        }

        emit PositionClosed(
            msg.sender,
            positionAccount,
            position.cycleId,
            closeFractionBps,
            shortAmountToRepayForFirstSwap + amountToRepaySecond,
            longAmountToRedeemForFirstSwap,
            dsaAmountRedeemed,
            longDustRedeemed
        );
    }

    /**
     * @notice Withdraws principal from an active position, subject to utilization constraints
     * @dev Only callable when the position is active. Calculates utilization and withdraws up to the
     *      requested amount, bounded by the withdrawable principal derived from utilization.
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @param amount Amount to withdraw
     * @custom:error Throw ZeroAddress if no position account exists for this user/markets pair.
     * @custom:error Throw PositionNotActive if the position is not active.
     * @custom:error Throw ZeroAmount if amount is zero.
     * @custom:error Throw InsufficientWithdrawableAmount if amount exceeds withdrawable principal.
     * @custom:error Throw RedeemBehalfFailed if redeem fails.
     * @custom:event Emits PrincipalWithdrawn event when principal is withdrawn.
     */
    function withdrawPrincipal(
        IVToken longVToken,
        IVToken shortVToken,
        uint256 amount
    ) external nonReentrant whenNotPaused {
        if (amount == 0) revert ZeroAmount();

        Position storage position = _getActivePosition(msg.sender, address(longVToken), address(shortVToken));
        address positionAccount = position.positionAccount;

        UtilizationInfo memory utilization = _getUtilizationInfo(position);
        if (amount > utilization.withdrawableAmount) revert InsufficientWithdrawableAmount();

        IVToken dsaVToken = IVToken(position.dsaVToken);
        uint256 vTokensBefore = dsaVToken.balanceOf(positionAccount);
        _redeemUnderlyingToUser(dsaVToken, positionAccount, amount);
        uint256 vTokensAfter = dsaVToken.balanceOf(positionAccount);

        // Reduce suppliedPrincipalVTokens by DSA vTokens burned for this withdraw, clamped to tracked principal.
        uint256 burned = vTokensBefore - vTokensAfter;
        if (burned > position.suppliedPrincipalVTokens) {
            position.suppliedPrincipalVTokens = 0;
        } else {
            position.suppliedPrincipalVTokens -= burned;
        }

        emit PrincipalWithdrawn(
            msg.sender,
            positionAccount,
            address(dsaVToken),
            amount,
            position.suppliedPrincipalVTokens
        );
    }

    /**
     * @notice Deactivates a position account
     * @dev Reverts if position still has long collateral or short debt (PositionNotFullyClosed).
     *      Withdraws all remaining DSA principal to the user, then sets isActive False.
     *      User may activate again later (possibly with a different DSA via dsaIndex).
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @custom:error Throw PositionNotActive if the position is not active.
     * @custom:error Throw PositionNotFullyClosed if long collateral or short debt remains.
     * @custom:event Emits PositionDeactivated event.
     */
    function deactivatePosition(IVToken longVToken, IVToken shortVToken) external nonReentrant whenNotPaused {
        Position storage position = _getActivePosition(msg.sender, address(longVToken), address(shortVToken));
        address positionAccount = position.positionAccount;

        // Check that position is fully closed: no long collateral and no short debt
        uint256 longCollateral = _getLongCollateralBalance(position);
        uint256 shortDebt = shortVToken.borrowBalanceCurrent(positionAccount);

        if (longCollateral > 0 || shortDebt > 0) revert PositionNotFullyClosed();
        IVToken dsaVToken = IVToken(position.dsaVToken);

        position.isActive = false;
        position.suppliedPrincipalVTokens = 0;

        // Withdraw any remaining DSA principal to user (for complete withdraw use redeemBehalf insted of redeemUnderlyingToUser)
        uint256 underlyingRedeemed = _redeemAllVTokensToUser(dsaVToken, positionAccount);
        emit PositionDeactivated(msg.sender, positionAccount, position.cycleId, address(dsaVToken), underlyingRedeemed);
    }

    /**
     * @notice Returns the address at which the PositionAccount would be deployed for the given user and markets
     * @dev Uses the same salt as _deployPositionAccount (keccak256(user, longVToken, shortVToken)).
     *      Returns the address that cloneDeterministic would deploy to if called by this contract.
     * @param user User address
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @return predicted The predicted PositionAccount address (same as after activatePosition for that user/long/short)
     * @custom:error Throw PositionAccountImplementationNotSet if implementation is not configured.
     */
    function getPositionAccountAddress(
        address user,
        IVToken longVToken,
        IVToken shortVToken
    ) external view returns (address predicted) {
        if (POSITION_ACCOUNT_IMPLEMENTATION == address(0)) {
            revert PositionAccountImplementationNotSet();
        }

        bytes32 salt = keccak256(abi.encodePacked(user, address(longVToken), address(shortVToken)));
        return ClonesUpgradeable.predictDeterministicAddress(POSITION_ACCOUNT_IMPLEMENTATION, salt, address(this));
    }

    /**
     * @notice Returns the full list of configured DSA vToken markets
     * @return dsaVTokensList Array of DSA vToken addresses
     */
    function getDsaVTokens() external view returns (address[] memory dsaVTokensList) {
        dsaVTokensList = new address[](dsaVTokenIndexCounter);
        for (uint8 i = 0; i < dsaVTokenIndexCounter; i++) {
            dsaVTokensList[i] = dsaVTokens[i];
        }
    }

    /**
     * @notice Returns the position data for a user and asset pair
     * @param user User address
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @return position The Position struct (user, longVToken, shortVToken, positionAccount, dsaIndex, dsaVToken, suppliedPrincipalVTokens, effectiveLeverage, cycleId, isActive)
     */
    function getPosition(
        address user,
        IVToken longVToken,
        IVToken shortVToken
    ) external view returns (Position memory position) {
        return positions[user][address(longVToken)][address(shortVToken)];
    }

    /**
     * @notice Calculates capital utilization for a position
     * @dev Computes how much capital is being used vs available. DSA is read from the position. See IRelativePositionManager for full description.
     * @param user User address
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @return utilization Utilization information including available capital and withdrawable amount
     */
    function getUtilizationInfo(
        address user,
        IVToken longVToken,
        IVToken shortVToken
    ) external returns (UtilizationInfo memory utilization) {
        Position storage position = positions[user][address(longVToken)][address(shortVToken)];
        return _getUtilizationInfo(position);
    }

    /**
     * @notice Calculates the maximum allowed borrow amount for a position
     * @dev Uses getUtilizationInfo internally. See IRelativePositionManager for full description.
     * @param user User address
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @return maxBorrowAmount Maximum amount that can be borrowed in shortAsset terms
     */
    function calculateMaxBorrow(
        address user,
        IVToken longVToken,
        IVToken shortVToken
    ) external returns (uint256 maxBorrowAmount) {
        Position storage position = positions[user][address(longVToken)][address(shortVToken)];
        return _calculateMaxBorrowAllowed(position);
    }

    /**
     * @notice Returns the actual long collateral balance in underlying for a given user/position,
     *         excluding DSA principal when the DSA and long assets share the same vToken market.
     * @dev This is a public wrapper around `_getLongCollateralBalance` intended primarily for tests
     *      and off-chain monitoring. It is not marked view because it may call `exchangeRateCurrent`
     *      on the vToken, which can update state.
     * @param user The position owner
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @return longBalance The long collateral balance in underlying units (principal excluded when shared market)
     */
    function getLongCollateralBalance(
        address user,
        IVToken longVToken,
        IVToken shortVToken
    ) external returns (uint256 longBalance) {
        Position storage position = positions[user][address(longVToken)][address(shortVToken)];
        return _getLongCollateralBalance(position);
    }

    /**
     * @notice Returns the supplied principal balance in underlying units for a given user/position
     * @dev When DSA != long, reads DSA underlying from position account. When DSA == long, uses stored vToken principal.
     *      Not view because it may call exchangeRateCurrent on the vToken.
     * @param user The position owner
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @return balance The supplied principal in underlying units
     */
    function getSuppliedPrincipalBalance(
        address user,
        IVToken longVToken,
        IVToken shortVToken
    ) external returns (uint256 balance) {
        Position storage position = positions[user][address(longVToken)][address(shortVToken)];
        return _getSuppliedPrincipalBalance(position);
    }

    /**
     * @notice Deploys a new PositionAccount contract for the user
     * @dev Uses deterministic deployment via clones and initializes the clone with user-specific data.
     *      Sets position account address and immutable position fields (user, longAsset, shortAsset) in storage.
     * @param user User address
     * @param longAsset Long asset vToken address
     * @param shortAsset Short asset vToken address
     */
    function _deployPositionAccount(address user, address longAsset, address shortAsset) internal {
        if (POSITION_ACCOUNT_IMPLEMENTATION == address(0)) {
            revert PositionAccountImplementationNotSet();
        }

        bytes32 salt = keccak256(abi.encodePacked(user, longAsset, shortAsset));
        address positionAccount = ClonesUpgradeable.cloneDeterministic(POSITION_ACCOUNT_IMPLEMENTATION, salt);

        // Initialize the clone with user-specific data (owner, longAsset, shortAsset)
        // This will automatically approve both RPM and LeverageManager as delegates
        IPositionAccount(positionAccount).initialize(user, longAsset, shortAsset);

        Position storage position = positions[user][longAsset][shortAsset];
        position.positionAccount = positionAccount;
        position.user = user;
        position.longVToken = longAsset;
        position.shortVToken = shortAsset;

        emit PositionAccountDeployed(user, longAsset, shortAsset, positionAccount);
    }

    /**
     * @notice Redeems a given amount of long from the position account and swaps it to DSA,
     *         then supplies the resulting DSA as additional principal on the same position.
     * @dev Used for proportional close with profit: partial or full close can have a "profit" slice converted
     *      into DSA principal. Does not require zero short debt (unlike _realizeProfitFromExcessLong).
     *      When DSA and long share the same vToken market, no redeem/mint cycle is required; the function
     *      simply reclassifies part of the long collateral as principal in storage.
     * @param position The Position storage reference whose principal should be increased
     * @param positionAccount The position account from which long is conceptually redeemed
     * @param longVToken Long market vToken
     * @param dsaVToken DSA market vToken
     * @param amountToRedeem Amount of long underlying to convert into DSA principal
     * @param minAmountOutProfit Minimum DSA out from the swap
     * @param swapDataProfit Calldata for the long→DSA swap
     */
    function _redeemLongAndSwapToDSA(
        Position storage position,
        address positionAccount,
        IVToken longVToken,
        IVToken dsaVToken,
        uint256 amountToRedeem,
        uint256 minAmountOutProfit,
        bytes calldata swapDataProfit
    ) internal {
        IERC20Upgradeable longUnderlying = IERC20Upgradeable(longVToken.underlying());
        IERC20Upgradeable dsaUnderlying = IERC20Upgradeable(dsaVToken.underlying());
        uint256 vTokensMinted;

        if (address(longUnderlying) == address(dsaUnderlying)) {
            // no on-chain redeem/swap/mint required. Reclassify long vTokens as principal.
            uint256 exchangeRate = dsaVToken.exchangeRateCurrent();
            vTokensMinted = (amountToRedeem * MANTISSA_ONE) / exchangeRate;
        } else {
            // Redeem long underlying from the position account to this contract
            uint256 err = longVToken.redeemUnderlyingBehalf(positionAccount, amountToRedeem);
            if (err != SUCCESS) revert RedeemBehalfFailed(err);

            uint256 amountOut = _performSwap(
                longUnderlying,
                amountToRedeem,
                dsaUnderlying,
                minAmountOutProfit,
                swapDataProfit
            );

            // Supply the received DSA underlying as additional principal to the same position account.
            uint256 balanceBefore = dsaVToken.balanceOf(positionAccount);
            dsaUnderlying.forceApprove(address(dsaVToken), amountOut);
            uint256 mintError = dsaVToken.mintBehalf(positionAccount, amountOut);
            if (mintError != SUCCESS) revert MintBehalfFailed(mintError);
            uint256 balanceAfter = dsaVToken.balanceOf(positionAccount) - balanceBefore;

            vTokensMinted = balanceAfter;
        }

        // Update principal state
        position.suppliedPrincipalVTokens += vTokensMinted;
        emit ProfitConverted(position.user, positionAccount, amountToRedeem, position.suppliedPrincipalVTokens);
    }

    /**
     * @notice Transfers token dust from position account to the position owner (msg.sender from the user's perspective)
     * @dev Calls PositionAccount.transferDustToOwner which is only callable by this manager; dust goes to account owner.
     * @param positionAccount Address of the position account holding the dust
     * @param tokenAddress Address of the ERC20 token to transfer
     */
    function _transferDustFromAccountToUser(address positionAccount, address tokenAddress) internal {
        IPositionAccount(positionAccount).transferDustToOwner(tokenAddress);
    }

    /**
     * @notice Redeems underlying from a vToken on behalf of an account and transfers the received underlying to msg.sender
     * @param vToken The vToken market to redeem from
     * @param fromAccount The account on whose behalf to redeem (e.g. position account)
     * @param amount Amount of underlying to redeem
     */
    function _redeemUnderlyingToUser(IVToken vToken, address fromAccount, uint256 amount) internal {
        if (amount == 0) return;
        IERC20Upgradeable underlying = IERC20Upgradeable(vToken.underlying());
        uint256 balanceBefore = underlying.balanceOf(address(this));
        uint256 err = vToken.redeemUnderlyingBehalf(fromAccount, amount);
        if (err != SUCCESS) revert RedeemBehalfFailed(err);
        uint256 received = underlying.balanceOf(address(this)) - balanceBefore;
        if (received > 0) {
            underlying.safeTransfer(msg.sender, received);
            emit UnderlyingTransferred(address(underlying), fromAccount, msg.sender, received);
        }
    }

    /**
     * @notice Verifies full close conditions and handles remaining long dust after a 100% close
     * @dev Only acts when closeFractionBps == 100. Verifies all short debt is repaid, then handles
     *      remaining long vTokens:
     *      - If long == DSA: reclassifies remaining long vTokens as principal (redeemed during deactivation)
     *      - If long != DSA: redeems remaining long vTokens directly to the user
     *      Uses redeemBehalf (vToken amount) instead of redeemUnderlyingBehalf (underlying amount)
     *      to avoid precision loss: when a small underlying dust amount is divided by the exchange rate,
     *      the result can truncate to 0 vTokens, causing the redeem to revert.
     * @param position The position storage reference
     * @param longVToken The long market vToken
     * @param shortVToken The short market vToken
     * @return longDustRedeemed The underlying amount redeemed (or reclassified) as dust
     */
    function _verifyFullClose(
        Position storage position,
        IVToken longVToken,
        IVToken shortVToken
    ) internal returns (uint256 longDustRedeemed) {
        address positionAccount = position.positionAccount;
        if (shortVToken.borrowBalanceCurrent(positionAccount) > 0) revert PositionNotFullyClosed();
        IVToken dsaVToken = IVToken(position.dsaVToken);

        if (address(longVToken) == address(dsaVToken)) {
            // Read long collateral (excludes current principal) before reclassifying.
            longDustRedeemed = _getLongCollateralBalance(position);
            // Set suppliedPrincipalVTokens to the full vToken balance.
            position.suppliedPrincipalVTokens = longVToken.balanceOf(positionAccount);
        } else {
            longDustRedeemed = _redeemAllVTokensToUser(longVToken, positionAccount);
        }
    }

    /**
     * @notice Redeems the full vToken balance from a position account and transfers all resulting underlying to the caller
     * @param vToken The vToken market to redeem from
     * @param positionAccount The position account on whose behalf to redeem
     * @return underlyingRedeemed Amount of underlying transferred to the caller
     */
    function _redeemAllVTokensToUser(
        IVToken vToken,
        address positionAccount
    ) internal returns (uint256 underlyingRedeemed) {
        uint256 vTokenBalance = vToken.balanceOf(positionAccount);
        if (vTokenBalance == 0) return 0;

        IERC20Upgradeable underlying = IERC20Upgradeable(vToken.underlying());
        uint256 balanceBefore = underlying.balanceOf(address(this));
        uint256 err = vToken.redeemBehalf(positionAccount, vTokenBalance);
        if (err != SUCCESS) revert RedeemBehalfFailed(err);
        underlyingRedeemed = underlying.balanceOf(address(this)) - balanceBefore;
        if (underlyingRedeemed > 0) {
            underlying.safeTransfer(msg.sender, underlyingRedeemed);
            emit UnderlyingTransferred(address(underlying), positionAccount, msg.sender, underlyingRedeemed);
        }
    }

    /**
     * @notice Transfers DSA underlying from msg.sender to this contract, approves and mints vTokens to the position account
     * @param position The position whose principal should be increased
     * @param dsaVToken The DSA vToken market
     * @param amount Amount of underlying to transfer and mint
     */
    function _supplyPrincipalToPositionAccount(Position storage position, IVToken dsaVToken, uint256 amount) internal {
        if (position.longVToken == address(dsaVToken)) _syncSuppliedPrincipal(position);
        address positionAccount = position.positionAccount;

        uint256 balanceBefore = dsaVToken.balanceOf(positionAccount);
        address underlying = dsaVToken.underlying();
        IERC20Upgradeable(underlying).safeTransferFrom(msg.sender, address(this), amount);
        IERC20Upgradeable(underlying).forceApprove(address(dsaVToken), amount);
        uint256 mintError = dsaVToken.mintBehalf(positionAccount, amount);
        if (mintError != SUCCESS) revert MintBehalfFailed(mintError);
        uint256 vTokensMinted = dsaVToken.balanceOf(positionAccount) - balanceBefore;
        position.suppliedPrincipalVTokens += vTokensMinted;

        emit PrincipalSupplied(
            position.user,
            positionAccount,
            position.cycleId,
            address(dsaVToken),
            amount,
            position.suppliedPrincipalVTokens
        );
    }

    /**
     * @notice Performs token swap via the LeverageManager's SwapHelper
     * @dev Transfers tokenIn to SwapHelper, executes param (calldata), then verifies tokenOut received >= minAmountOut.
     *      Reverts with TokenSwapCallFailed if the call fails, SlippageExceeded if output < minAmountOut.
     * @param tokenIn The input token (transferred to SwapHelper)
     * @param amountIn The amount of input tokens to swap
     * @param tokenOut The output token (received by this contract)
     * @param minAmountOut The minimum acceptable amount of output tokens (slippage protection)
     * @param param The encoded swap calldata for the SwapHelper
     * @return amountOut The actual amount of output tokens received
     */
    function _performSwap(
        IERC20Upgradeable tokenIn,
        uint256 amountIn,
        IERC20Upgradeable tokenOut,
        uint256 minAmountOut,
        bytes calldata param
    ) internal returns (uint256 amountOut) {
        address swapHelperAddr = address(LEVERAGE_MANAGER.swapHelper());
        tokenIn.safeTransfer(swapHelperAddr, amountIn);

        uint256 tokenOutBalanceBefore = tokenOut.balanceOf(address(this));

        (bool success, ) = swapHelperAddr.call(param);
        if (!success) revert TokenSwapCallFailed();

        uint256 tokenOutBalanceAfter = tokenOut.balanceOf(address(this));
        amountOut = tokenOutBalanceAfter - tokenOutBalanceBefore;
        if (amountOut < minAmountOut) revert SlippageExceeded();
    }

    /**
     * @notice Calculates the maximum allowed borrow amount for a position
     * @param position In-memory snapshot of the position data
     * @return maxBorrowAmount Maximum amount that can be borrowed in shortAsset terms
     */
    function _calculateMaxBorrowAllowed(Position storage position) internal returns (uint256 maxBorrowAmount) {
        // Get utilization info which calculates available capital (DSA from position)
        UtilizationInfo memory utilization = _getUtilizationInfo(position);

        // Calculate max additional borrow amount: availableCapital * effectiveLeverage
        uint256 maxAdditionalBorrowUSD = (utilization.availableCapitalUSD * position.effectiveLeverage) / MANTISSA_ONE;

        // Convert to shortAsset amount
        ResilientOracleInterface oracle = COMPTROLLER.oracle();
        uint256 shortPrice = oracle.getUnderlyingPrice(position.shortVToken);

        maxBorrowAmount = (maxAdditionalBorrowUSD * MANTISSA_ONE) / shortPrice;
    }

    /**
     * @notice Calculates capital utilization for a position (used for max borrow and withdrawable amount)
     * @dev Computes actualCapitalUtilized (LTV-based), nominalCapitalUtilized (leverage-based), caps by supplied principal,
     *      then availableCapitalUSD and withdrawableAmount in DSA terms.
     * @param position In-memory snapshot of the position data
     * @return utilization Struct with actualCapitalUtilized, nominalCapitalUtilized, finalCapitalUtilized, availableCapitalUSD, withdrawableAmount
     */
    function _getUtilizationInfo(Position storage position) internal returns (UtilizationInfo memory utilization) {
        IVToken longVToken = IVToken(position.longVToken);
        PositionValuesUSD memory values = _getPositionValuesUSD(position);
        IVToken dsaVToken = IVToken(position.dsaVToken);

        (, uint256 dsaCF, ) = COMPTROLLER.markets(address(dsaVToken));
        (, uint256 longCF, ) = COMPTROLLER.markets(address(longVToken));

        // Calculate nominalCapitalUtilized borrowValueUSD/effectiveLeverage
        utilization.nominalCapitalUtilized = (values.borrowValueUSD * MANTISSA_ONE) / position.effectiveLeverage;

        // Calculate actualCapitalUtilized (borrowValueUSD - (longValueUSD * longCF) / dsaCF
        utilization.actualCapitalUtilized = values.borrowValueUSD > (values.longValueUSD * longCF) / MANTISSA_ONE
            ? ((values.borrowValueUSD - (values.longValueUSD * longCF) / MANTISSA_ONE) * MANTISSA_ONE) / dsaCF
            : 0;

        utilization.finalCapitalUtilized = max(utilization.actualCapitalUtilized, utilization.nominalCapitalUtilized);
        utilization.finalCapitalUtilized = min(values.suppliedPrincipalUSD, utilization.finalCapitalUtilized);

        // Calculate available capital in USD (finalCapitalUtilized is already capped by suppliedPrincipalVTokens)
        utilization.availableCapitalUSD = values.suppliedPrincipalUSD - utilization.finalCapitalUtilized;

        // Calculate withdrawable amount in DSA token terms
        utilization.withdrawableAmount = (utilization.availableCapitalUSD * MANTISSA_ONE) / values.dsaPrice;
    }

    /**
     * @notice Returns expected proportional amounts and tolerance band for a close (BPS of current balance/debt)
     * @dev Reverts with InvalidCloseFractionBps if closeFractionBps is not in [1, 100].
     * @param position The position (long balance and positionAccount from position; short debt from position.shortVToken)
     * @param closeFractionBps Proportion to close in percentage (100 = 100%, 1 = 1% minimum)
     * @return expectedLongToWithdraw Amount of long to redeem (BPS of current long balance)
     * @return expectedShortToRepay Amount of short to repay (BPS of current short debt)
     * @return minLongToWithdraw Minimum long amount within PROPORTIONAL_CLOSE_TOLERANCE
     * @return maxLongToWithdraw Maximum long amount within PROPORTIONAL_CLOSE_TOLERANCE
     * @return maxExpectedShortToRepay Expected short + tolerance (for 100% close / first-leg cap in loss close)
     */
    function _getProportionalCloseAmounts(
        Position storage position,
        uint256 closeFractionBps
    )
        internal
        returns (
            uint256 expectedLongToWithdraw,
            uint256 expectedShortToRepay,
            uint256 minLongToWithdraw,
            uint256 maxLongToWithdraw,
            uint256 maxExpectedShortToRepay
        )
    {
        if (closeFractionBps < PROPORTIONAL_CLOSE_MIN || closeFractionBps > PROPORTIONAL_CLOSE_MAX)
            revert InvalidCloseFractionBps();

        uint256 longBalance = _getLongCollateralBalance(position);
        IVToken shortVToken = IVToken(position.shortVToken);
        uint256 shortDebt = shortVToken.borrowBalanceCurrent(position.positionAccount);
        expectedLongToWithdraw = (longBalance * closeFractionBps) / PROPORTIONAL_CLOSE_MAX;
        expectedShortToRepay = (shortDebt * closeFractionBps) / PROPORTIONAL_CLOSE_MAX;

        minLongToWithdraw =
            (expectedLongToWithdraw * (PROPORTIONAL_CLOSE_MAX - PROPORTIONAL_CLOSE_TOLERANCE)) / PROPORTIONAL_CLOSE_MAX;
        maxLongToWithdraw =
            (expectedLongToWithdraw * (PROPORTIONAL_CLOSE_MAX + PROPORTIONAL_CLOSE_TOLERANCE)) / PROPORTIONAL_CLOSE_MAX;
        // Cap at actual long collateral balance to prevent out-of-band values
        maxLongToWithdraw = min(maxLongToWithdraw, longBalance);

        maxExpectedShortToRepay =
            (expectedShortToRepay * (PROPORTIONAL_CLOSE_MAX + PROPORTIONAL_CLOSE_TOLERANCE)) / PROPORTIONAL_CLOSE_MAX;
    }

    /**
     * @notice Validates proportional close for profit path and returns amount to repay
     * @dev Validates totalLongAmountToRedeem (repay + profit) within 2% of BPS expected. Reverts if out of band.
     * @param totalLongAmountToRedeem Sum of long to redeem for repay and for profit swap (collateralAmountToRedeem + amountToRedeemForProfitSwap)
     * @param minAmountOutRepay User's minimum expected short from repay swap; must be >= expected short for this BPS (slightly above current debt is enough)
     * @return amountToRepay Short amount to use for repay call (includes 100% tolerance bump when applicable)
     */
    function _validateProfitClose(
        Position storage position,
        uint256 closeFractionBps,
        uint256 totalLongAmountToRedeem,
        uint256 minAmountOutRepay
    ) internal returns (uint256 amountToRepay) {
        (
            uint256 expectedLongToWithdraw,
            uint256 expectedShortToRepay,
            uint256 minLongToWithdraw,
            uint256 maxLongToWithdraw,
            uint256 maxExpectedShortToRepay
        ) = _getProportionalCloseAmounts(position, closeFractionBps);

        // Revert when user tries to withdraw more than available long (BPS implies zero long to redeem).
        if (expectedLongToWithdraw == 0 && totalLongAmountToRedeem != 0) revert InvalidLongAmountToRedeem();

        // Revert if total long to redeem is outside the proportional close tolerance band.
        if (totalLongAmountToRedeem < minLongToWithdraw || totalLongAmountToRedeem > maxLongToWithdraw)
            revert ProportionalCloseAmountOutOfTolerance();

        // Validate minAmountOut against exact expected short (not bumped) to give user certainty on the repay amount
        if (expectedShortToRepay > 0 && minAmountOutRepay < expectedShortToRepay) revert MinAmountOutRepayBelowDebt();
        amountToRepay = (closeFractionBps == PROPORTIONAL_CLOSE_MAX && expectedShortToRepay > 0)
            ? maxExpectedShortToRepay // For 100% close, add tolerance so we send slightly more to cover interest during flash loan
            : expectedShortToRepay;
    }

    /**
     * @notice Validates loss close first exit and returns calculated second repay amount
     * @dev Ensures the provided first-leg long/short amounts are within the proportional-close tolerance band
     *      and derives the second-leg short repay amount (with tolerance bump for 100% closes).
     *      If first-leg short > expected, full close in first leg is allowed provided it is <= maxExpectedShortToRepay (second leg = 0).
     * @param position snapshot of the position (used to derive expected long/short amounts)
     * @param closeFractionBps Proportion to close in percentage (100 = 100%, 1 = 1% minimum)
     * @param shortAmountToRepayForFirstSwap Short amount to repay in the first exit, for 100% close with one leg, should cover the extra bumped amount.
     * @param longAmountToRedeemForFirstSwap Long amount to redeem for the first swap (must be within PROPORTIONAL_CLOSE_TOLERANCE of expected long)
     * @param minAmountOutFirst Minimum short out from the first swap (must be >= shortAmountToRepayForFirstSwap
     * @param minAmountOutSecond Minimum short out from the second swap (must be >= internally calculated second repay; for 100% close should cover the bumped amount)
     * @return amountToRepaySecond The second-leg short repay amount (expectedShortToRepay - first leg, or 0 when first leg covers full). Caller uses shortAmountToRepayForFirstSwap for the first leg.
     */
    function _validateLossClose(
        Position storage position,
        uint256 closeFractionBps,
        uint256 longAmountToRedeemForFirstSwap,
        uint256 shortAmountToRepayForFirstSwap,
        uint256 minAmountOutFirst,
        uint256 minAmountOutSecond
    ) internal returns (uint256 amountToRepaySecond) {
        // MinimumOut should never be smaller than expected to repay; for 100% close with one asset, user should account for the extra bumped amount (similar to profit case).
        if (minAmountOutFirst < shortAmountToRepayForFirstSwap) revert MinAmountOutRepayBelowDebt();

        (
            uint256 expectedLongToWithdraw,
            uint256 expectedShortToRepay,
            uint256 minLongToWithdraw,
            uint256 maxLongToWithdraw,
            uint256 maxExpectedShortToRepay
        ) = _getProportionalCloseAmounts(position, closeFractionBps);

        // Revert when user tries to withdraw more than available long (BPS implies zero long to redeem).
        if (expectedLongToWithdraw == 0 && longAmountToRedeemForFirstSwap != 0) revert InvalidLongAmountToRedeem();

        // Revert if first-leg long to redeem is outside the proportional close tolerance band.
        if (longAmountToRedeemForFirstSwap < minLongToWithdraw || longAmountToRedeemForFirstSwap > maxLongToWithdraw)
            revert ProportionalCloseAmountOutOfTolerance();

        // First leg exceeds expected: cap at maxExpectedShortToRepay and set second leg to zero.
        if (shortAmountToRepayForFirstSwap > expectedShortToRepay) {
            if (shortAmountToRepayForFirstSwap > maxExpectedShortToRepay)
                revert ProportionalCloseAmountOutOfTolerance();
            amountToRepaySecond = 0;
        } else {
            amountToRepaySecond = expectedShortToRepay - shortAmountToRepayForFirstSwap;
        }

        // Validate and optionally bump second leg.
        if (amountToRepaySecond > 0) {
            if (minAmountOutSecond < amountToRepaySecond) revert MinAmountOutSecondBelowDebt();
            if (closeFractionBps == PROPORTIONAL_CLOSE_MAX) {
                amountToRepaySecond =
                    (amountToRepaySecond * (PROPORTIONAL_CLOSE_MAX + PROPORTIONAL_CLOSE_TOLERANCE)) /
                    PROPORTIONAL_CLOSE_MAX;
            }
        }
        return amountToRepaySecond;
    }

    /**
     * @notice Caps stored suppliedPrincipalVTokens to the position account's DSA vToken balance and emits if updated.
     * @dev Only meaningful when DSA == long: external liquidations can seize vTokens without updating this contract,
     *      so stored suppliedPrincipalVTokens may exceed the actual balance. This sync keeps state consistent.
     * @param position Position to sync (suppliedPrincipalVTokens and positionAccount must be set)
     */
    function _syncSuppliedPrincipal(Position storage position) internal {
        uint256 vTokenBalance = IVToken(position.dsaVToken).balanceOf(position.positionAccount);
        if (position.suppliedPrincipalVTokens > vTokenBalance) {
            uint256 oldSuppliedPrincipal = position.suppliedPrincipalVTokens;
            position.suppliedPrincipalVTokens = vTokenBalance;
            emit RefreshedSuppliedPrincipal(
                position.user,
                position.positionAccount,
                oldSuppliedPrincipal,
                vTokenBalance
            );
        }
    }

    /**
     * @notice Converts supplied principal to underlying amount, handling DSA==long and DSA!=long cases
     * @dev When DSA != long asset, all DSA underlying on the position account is considered principal,
     *      so we can read it directly. When DSA == long asset, we must use the stored principal vTokens
     *      to avoid counting long collateral as principal.
     * @param position The position data (holds suppliedPrincipalVTokens and positionAccount)
     * @return balance of principal in underlying units
     */
    function _getSuppliedPrincipalBalance(Position storage position) internal returns (uint256) {
        address positionAccount = position.positionAccount;
        if (positionAccount == address(0)) revert ZeroAddress();

        IVToken longVToken = IVToken(position.longVToken);
        IVToken dsaVToken = IVToken(position.dsaVToken);

        // When DSA == long, principal is tracked in vTokens to separate it from long collateral.
        if (address(dsaVToken) == address(longVToken)) {
            _syncSuppliedPrincipal(position);
            uint256 exchangeRate = dsaVToken.exchangeRateCurrent();
            return (position.suppliedPrincipalVTokens * exchangeRate) / MANTISSA_ONE;
        }

        // DSA and long are different assets: all DSA underlying on the position is principal.
        return dsaVToken.balanceOfUnderlying(positionAccount);
    }

    /**
     * @notice Gets the actual long collateral balance, excluding DSA principal if DSA == long asset
     * @param position The position data
     * @return longBalance The actual long collateral balance in underlying (excluding DSA principal if DSA == long)
     */
    function _getLongCollateralBalance(Position storage position) internal returns (uint256 longBalance) {
        address positionAccount = position.positionAccount;
        if (positionAccount == address(0)) revert ZeroAddress();

        IVToken longVToken = IVToken(position.longVToken);
        IVToken dsaVToken = IVToken(position.dsaVToken);

        if (address(longVToken) == address(dsaVToken)) {
            // Same asset: sync supplied principal, then long collateral = vToken balance minus supplied principal.
            _syncSuppliedPrincipal(position);
            uint256 vTokenBalance = longVToken.balanceOf(positionAccount);
            uint256 longVTokensNet = vTokenBalance - position.suppliedPrincipalVTokens;
            if (longVTokensNet == 0) return 0;
            uint256 exchangeRate = longVToken.exchangeRateCurrent();
            return (longVTokensNet * exchangeRate) / MANTISSA_ONE;
        }

        return longVToken.balanceOfUnderlying(positionAccount);
    }

    /**
     * @notice Returns USD values of long collateral, short debt (borrow), and supplied principal
     * @param position The position data (longVToken, shortVToken, dsaVToken read from position)
     * @return values Struct with longValueUSD, borrowValueUSD, suppliedPrincipalUSD, dsaPrice, shortPrice
     */
    function _getPositionValuesUSD(Position storage position) internal returns (PositionValuesUSD memory values) {
        IVToken longVToken = IVToken(position.longVToken);
        IVToken shortVToken = IVToken(position.shortVToken);
        IVToken dsaVToken = IVToken(position.dsaVToken);
        address positionAccount = position.positionAccount;
        uint256 longCollateral = _getLongCollateralBalance(position);
        uint256 shortDebt = shortVToken.borrowBalanceCurrent(positionAccount);
        uint256 suppliedPrincipal = _getSuppliedPrincipalBalance(position);

        ResilientOracleInterface oracle = COMPTROLLER.oracle();
        uint256 longPrice = oracle.getUnderlyingPrice(address(longVToken));
        values.shortPrice = oracle.getUnderlyingPrice(address(shortVToken));
        values.dsaPrice = oracle.getUnderlyingPrice(address(dsaVToken));

        if (longPrice == 0 || values.shortPrice == 0 || values.dsaPrice == 0) {
            revert InvalidOraclePrice();
        }

        values.longValueUSD = (longCollateral * longPrice) / MANTISSA_ONE;
        values.borrowValueUSD = (shortDebt * values.shortPrice) / MANTISSA_ONE;
        values.suppliedPrincipalUSD = (suppliedPrincipal * values.dsaPrice) / MANTISSA_ONE;
    }

    /**
     * @notice Returns the DSA vToken for a given index; validates address and market listed. Only used at activation.
     * @param dsaIndex Index of the DSA vToken in the dsaVTokens array
     * @return dsaVToken The validated DSA vToken market
     */
    function _getValidatedDSAVToken(uint8 dsaIndex) internal view returns (IVToken dsaVToken) {
        if (dsaIndex >= dsaVTokenIndexCounter) revert InvalidDSA();
        address dsaVTokenAddr = dsaVTokens[dsaIndex];
        if (!isDsaVTokenActive[dsaVTokenAddr]) revert DSAInactive();

        dsaVToken = IVToken(dsaVTokenAddr);
        _checkMarketListed(dsaVTokenAddr);
    }

    /**
     * @notice Enters a market on behalf of the user if not already a member
     * @dev Skips enter if COMPTROLLER.checkMembership(user, market) is true; otherwise calls enterMarketBehalf and reverts on failure.
     * @param user Address to enter the market on behalf of (e.g. position account)
     * @param market The vToken market to enter
     */
    function _validateAndEnterMarket(address user, IVToken market) internal {
        if (!COMPTROLLER.checkMembership(user, market)) {
            uint256 err = COMPTROLLER.enterMarketBehalf(user, address(market));
            if (err != SUCCESS) revert EnterMarketFailed(err);
        }
    }

    /**
     * @notice Computes the maximum allowed leverage: λ_max = CF_c / (1 - CF_l * (1 - f))
     * @dev c = Collateral (DSA), L = Long asset, S = Short asset. CF_c = collateral CF, CF_l = Long asset CF, f = friction (PROPORTIONAL_CLOSE_TOLERANCE).
     * @param dsaVToken Collateral (DSA) vToken market
     * @param longVToken Long asset vToken market (CF_l)
     * @return maxLeverage The maximum leverage ratio allowed (1e18 mantissa)
     */
    function _getMaxLeverage(IVToken dsaVToken, address longVToken) internal view returns (uint256 maxLeverage) {
        (, uint256 cfC, ) = COMPTROLLER.markets(address(dsaVToken));
        if (cfC >= MANTISSA_ONE) revert InvalidCollateralFactor();

        (, uint256 cfL, ) = COMPTROLLER.markets(longVToken);
        if (cfL >= MANTISSA_ONE) revert InvalidCollateralFactor();

        // (1 - f) in mantissa: f = tolerance (slippage)
        uint256 friction = (PROPORTIONAL_CLOSE_TOLERANCE * MANTISSA_ONE) / PROPORTIONAL_CLOSE_MAX;
        uint256 oneMinusF = MANTISSA_ONE - friction;
        uint256 denom = MANTISSA_ONE - (cfL * oneMinusF) / MANTISSA_ONE; // 1 - CF_l * (1 - f)
        if (denom == 0) revert InvalidCollateralFactor();
        maxLeverage = (cfC * MANTISSA_ONE) / denom;
        if (maxLeverage < MIN_LEVERAGE) maxLeverage = MIN_LEVERAGE;
    }

    /**
     * @notice Reverts if long and short market are the same
     * @param longVToken Long market address
     * @param shortVToken Short market address
     */
    function _checkSameMarket(address longVToken, address shortVToken) internal pure {
        if (longVToken == shortVToken) revert SameMarketNotAllowed();
    }

    /**
     * @notice Validates that a market is listed in the Comptroller and is not vBNB
     * @dev Reverts with AssetNotListed if not listed, VBNBNotSupported if market is the leverage manager's vBNB.
     * @param market The vToken market address to validate
     */
    function _checkMarketListed(address market) internal view {
        if (market == address(0)) revert ZeroAddress();

        (bool isListed, , ) = COMPTROLLER.markets(market);
        if (!isListed) revert AssetNotListed();
        if (market == address(LEVERAGE_MANAGER.vBNB())) revert VBNBNotSupported();
    }

    /**
     * @notice Loads a position for a user/market pair and ensures it is active
     * @param user The position owner
     * @param longVToken Long market address
     * @param shortVToken Short market address
     * @return position The active Position storage reference
     */
    function _getActivePosition(
        address user,
        address longVToken,
        address shortVToken
    ) internal view returns (Position storage position) {
        position = positions[user][longVToken][shortVToken];
        if (!position.isActive) revert PositionNotActive();
    }

    /**
     * @notice Returns the maximum of two values
     * @param a First value
     * @param b Second value
     * @return The greater of a and b
     */
    function max(uint256 a, uint256 b) internal pure returns (uint256) {
        return a >= b ? a : b;
    }

    /**
     * @notice Returns the minimum of two values
     * @param a First value
     * @param b Second value
     * @return The lesser of a and b
     */
    function min(uint256 a, uint256 b) internal pure returns (uint256) {
        return a <= b ? a : b;
    }
}

